const APLUS_COURSE=[{"id": "core1-1.1", "title": "Repair mobile hardware safely", "core": 1, "objective": "1.1", "domain": 1, "type": "physical", "requires": [], "lore": "Check service documentation, power isolation, battery condition, and replaceability before opening a mobile device. Some parts are paired, glued, or not field-serviceable.\n\nYOUR TOOLKIT\n\nSwollen battery — A potentially hazardous battery condition requiring cessation of use and appropriate professional handling.\n\nReplaceable module — A component intended to be changed under the manufacturer's service procedure.\n\nESD protection — Measures limiting electrostatic discharge damage while handling sensitive electronics.\n\nService manual — Model-specific instructions establishing compatible parts and safe disassembly.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A swollen battery lifts a laptop trackpad. Stop using and charging the device and follow approved battery handling rather than pressing the case shut.", "questions": [{"id": "core1-1.1-practice-1-1-0", "prompt": "Which concept best fits this description? A potentially hazardous battery condition requiring cessation of use and appropriate professional handling.", "options": ["Replaceable module", "Service manual", "ESD protection", "Swollen battery"], "answer": 3, "explanation": "Swollen battery: A potentially hazardous battery condition requiring cessation of use and appropriate professional handling. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-1.1-practice-1-1-1", "prompt": "Which concept best fits this description? A component intended to be changed under the manufacturer's service procedure.", "options": ["Swollen battery", "Service manual", "Replaceable module", "ESD protection"], "answer": 2, "explanation": "Replaceable module: A component intended to be changed under the manufacturer's service procedure. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-1.1-match-1-1", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Swollen battery", "Replaceable module", "ESD protection", "Service manual"], "options": ["Measures limiting electrostatic discharge damage while handling sensitive electronics.", "A potentially hazardous battery condition requiring cessation of use and appropriate professional handling.", "Model-specific instructions establishing compatible parts and safe disassembly.", "A component intended to be changed under the manufacturer's service procedure."], "answer": [1, 3, 0, 2], "explanation": "Swollen battery: A potentially hazardous battery condition requiring cessation of use and appropriate professional handling.\nReplaceable module: A component intended to be changed under the manufacturer's service procedure.\nESD protection: Measures limiting electrostatic discharge damage while handling sensitive electronics.\nService manual: Model-specific instructions establishing compatible parts and safe disassembly.", "tier": 2}, {"id": "core1-1.1-scenario-1-1-0", "prompt": "A laptop case is bulging and the trackpad has lifted. The battery area is swollen.\n\nWhat should you do?", "options": ["Stop use and charging and follow safe battery-service procedures", "Press the case flat", "Puncture the battery to release pressure"], "answer": 0, "explanation": "A swollen battery is a safety issue, not a fitment issue.", "tier": 3}, {"id": "core1-1.1-scenario-1-1-1", "prompt": "A laptop case is bulging and the trackpad has lifted. The battery area is swollen.\n\nWhich repair source should guide replacement?", "options": ["An unrelated laptop video", "The model-specific service and battery-handling instructions", "A guess based on connector color"], "answer": 1, "explanation": "Model-specific safe handling and compatible parts are required.", "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-1.2", "title": "Connect accessories with the right capability", "core": 1, "objective": "1.2", "domain": 1, "type": "physical", "requires": ["core1-1.1"], "lore": "Connector shape alone does not establish power, speed, video, or protocol support. Check the device, cable, accessory, and port specifications together.\n\nYOUR TOOLKIT\n\nUSB-C — A reversible connector whose supported data, power, and video functions depend on implementation.\n\nDocking station — An accessory expanding connections such as displays, network, and peripherals.\n\nBluetooth pairing — An approved association between nearby devices for supported wireless profiles.\n\nNFC — Short-range communication used for interactions such as tap-to-pair or contactless transactions.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A USB-C dock charges a laptop but provides no display. Verify the required video mode and port support rather than assuming every USB-C connection carries video.", "questions": [{"id": "core1-1.2-practice-1-2-0", "prompt": "Which concept best fits this description? A reversible connector whose supported data, power, and video functions depend on implementation.", "options": ["Docking station", "NFC", "Bluetooth pairing", "USB-C"], "answer": 3, "explanation": "USB-C: A reversible connector whose supported data, power, and video functions depend on implementation. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-1.2-practice-1-2-1", "prompt": "Which concept best fits this description? An accessory expanding connections such as displays, network, and peripherals.", "options": ["USB-C", "NFC", "Docking station", "Bluetooth pairing"], "answer": 2, "explanation": "Docking station: An accessory expanding connections such as displays, network, and peripherals. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-1.2-match-1-2", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["USB-C", "Docking station", "Bluetooth pairing", "NFC"], "options": ["An approved association between nearby devices for supported wireless profiles.", "A reversible connector whose supported data, power, and video functions depend on implementation.", "Short-range communication used for interactions such as tap-to-pair or contactless transactions.", "An accessory expanding connections such as displays, network, and peripherals."], "answer": [1, 3, 0, 2], "explanation": "USB-C: A reversible connector whose supported data, power, and video functions depend on implementation.\nDocking station: An accessory expanding connections such as displays, network, and peripherals.\nBluetooth pairing: An approved association between nearby devices for supported wireless profiles.\nNFC: Short-range communication used for interactions such as tap-to-pair or contactless transactions.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-1.3", "title": "Support mobile connections and applications", "core": 1, "objective": "1.3", "domain": 1, "type": "physical", "requires": ["core1-1.2"], "lore": "Distinguish local Wi-Fi, cellular service, Bluetooth, synchronization, and account configuration. Protect business data when devices mix work and personal use.\n\nYOUR TOOLKIT\n\nTethering — Sharing a device's network connection with another device.\n\nHotspot — A wireless access service through which other devices can use an upstream connection.\n\nMDM enrollment — Registering a mobile device for centrally managed settings and policy.\n\nSynchronization — Keeping selected account or application data consistent across endpoints and services.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "Mail works on Wi-Fi but not cellular. Check mobile data permissions and connectivity before resetting the mailbox password.", "questions": [{"id": "core1-1.3-practice-1-3-0", "prompt": "Which concept best fits this description? Sharing a device's network connection with another device.", "options": ["Hotspot", "Synchronization", "MDM enrollment", "Tethering"], "answer": 3, "explanation": "Tethering: Sharing a device's network connection with another device. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-1.3-practice-1-3-1", "prompt": "Which concept best fits this description? A wireless access service through which other devices can use an upstream connection.", "options": ["Tethering", "Synchronization", "Hotspot", "MDM enrollment"], "answer": 2, "explanation": "Hotspot: A wireless access service through which other devices can use an upstream connection. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-1.3-match-1-3", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Tethering", "Hotspot", "MDM enrollment", "Synchronization"], "options": ["Registering a mobile device for centrally managed settings and policy.", "Sharing a device's network connection with another device.", "Keeping selected account or application data consistent across endpoints and services.", "A wireless access service through which other devices can use an upstream connection."], "answer": [1, 3, 0, 2], "explanation": "Tethering: Sharing a device's network connection with another device.\nHotspot: A wireless access service through which other devices can use an upstream connection.\nMDM enrollment: Registering a mobile device for centrally managed settings and policy.\nSynchronization: Keeping selected account or application data consistent across endpoints and services.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-2.1", "title": "Read common ports and transport", "core": 1, "objective": "2.1", "domain": 2, "type": "network", "requires": [], "lore": "Learn protocol purpose alongside default ports. A listening port is an entry point, not proof that the intended secure service is running.\n\nYOUR TOOLKIT\n\nSSH — Encrypted remote administration commonly using TCP22.\n\nDNS — Name resolution commonly using UDP53 and TCP53.\n\nHTTPS — TLS-protected web traffic commonly using TCP443.\n\nRDP — Remote graphical Windows access commonly associated with port3389 and requiring restricted secure deployment.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "Remote administration should use a protected protocol. Prefer SSH over plaintext Telnet when supported and appropriately configured.", "questions": [{"id": "core1-2.1-practice-2-1-0", "prompt": "Which concept best fits this description? Encrypted remote administration commonly using TCP22.", "options": ["RDP", "HTTPS", "SSH", "DNS"], "answer": 2, "explanation": "SSH: Encrypted remote administration commonly using TCP22. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-2.1-practice-2-1-1", "prompt": "Which concept best fits this description? Name resolution commonly using UDP53 and TCP53.", "options": ["RDP", "DNS", "HTTPS", "SSH"], "answer": 1, "explanation": "DNS: Name resolution commonly using UDP53 and TCP53. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-2.1-match-2-1", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["SSH", "DNS", "HTTPS", "RDP"], "options": ["TLS-protected web traffic commonly using TCP443.", "Encrypted remote administration commonly using TCP22.", "Remote graphical Windows access commonly associated with port3389 and requiring restricted secure deployment.", "Name resolution commonly using UDP53 and TCP53."], "answer": [1, 3, 0, 2], "explanation": "SSH: Encrypted remote administration commonly using TCP22.\nDNS: Name resolution commonly using UDP53 and TCP53.\nHTTPS: TLS-protected web traffic commonly using TCP443.\nRDP: Remote graphical Windows access commonly associated with port3389 and requiring restricted secure deployment.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-2.2", "title": "Choose wireless technology", "core": 1, "objective": "2.2", "domain": 2, "type": "network", "requires": ["core1-2.1"], "lore": "Bands, channels, security, interference, and device compatibility determine actual wireless performance. Match standards to the client and environment.\n\nYOUR TOOLKIT\n\n2.4 GHz band — A widely supported wireless band often crowded by overlapping networks and other devices.\n\n5 GHz band — A wireless band offering additional channels with range and penetration tradeoffs.\n\n6 GHz band — Additional spectrum used by compatible modern Wi-Fi equipment with regulatory and device constraints.\n\nWPA3 — A wireless security generation offering stronger authentication protections when correctly supported and configured.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A smart device supports only 2.4 GHz. A 5-GHz-only network cannot serve it without compatible support.", "questions": [{"id": "core1-2.2-practice-2-2-0", "prompt": "Which concept best fits this description? A widely supported wireless band often crowded by overlapping networks and other devices.", "options": ["WPA3", "6 GHz band", "2.4 GHz band", "5 GHz band"], "answer": 2, "explanation": "2.4 GHz band: A widely supported wireless band often crowded by overlapping networks and other devices. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-2.2-practice-2-2-1", "prompt": "Which concept best fits this description? A wireless band offering additional channels with range and penetration tradeoffs.", "options": ["WPA3", "5 GHz band", "6 GHz band", "2.4 GHz band"], "answer": 1, "explanation": "5 GHz band: A wireless band offering additional channels with range and penetration tradeoffs. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-2.2-match-2-2", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["2.4 GHz band", "5 GHz band", "6 GHz band", "WPA3"], "options": ["Additional spectrum used by compatible modern Wi-Fi equipment with regulatory and device constraints.", "A widely supported wireless band often crowded by overlapping networks and other devices.", "A wireless security generation offering stronger authentication protections when correctly supported and configured.", "A wireless band offering additional channels with range and penetration tradeoffs."], "answer": [1, 3, 0, 2], "explanation": "2.4 GHz band: A widely supported wireless band often crowded by overlapping networks and other devices.\n5 GHz band: A wireless band offering additional channels with range and penetration tradeoffs.\n6 GHz band: Additional spectrum used by compatible modern Wi-Fi equipment with regulatory and device constraints.\nWPA3: A wireless security generation offering stronger authentication protections when correctly supported and configured.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-2.3", "title": "Identify network-host services", "core": 1, "objective": "2.3", "domain": 2, "type": "network", "requires": ["core1-2.2"], "lore": "A service role is distinct from the device hosting it. One server can supply several roles, but each needs appropriate access, configuration, and resilience.\n\nYOUR TOOLKIT\n\nDHCP server — Leases network configuration to clients.\n\nDNS server — Answers name-resolution queries using authoritative data or recursive resolution.\n\nFile server — Provides shared file access subject to permissions and protocol settings.\n\nPrint server — Coordinates shared printing, queues, and client access to printers.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A user can reach a server by IP but not name. Investigate DNS rather than replacing a printer driver.", "questions": [{"id": "core1-2.3-practice-2-3-0", "prompt": "Which concept best fits this description? Leases network configuration to clients.", "options": ["Print server", "File server", "DHCP server", "DNS server"], "answer": 2, "explanation": "DHCP server: Leases network configuration to clients. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-2.3-practice-2-3-1", "prompt": "Which concept best fits this description? Answers name-resolution queries using authoritative data or recursive resolution.", "options": ["Print server", "DNS server", "File server", "DHCP server"], "answer": 1, "explanation": "DNS server: Answers name-resolution queries using authoritative data or recursive resolution. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-2.3-match-2-3", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["DHCP server", "DNS server", "File server", "Print server"], "options": ["Provides shared file access subject to permissions and protocol settings.", "Leases network configuration to clients.", "Coordinates shared printing, queues, and client access to printers.", "Answers name-resolution queries using authoritative data or recursive resolution."], "answer": [1, 3, 0, 2], "explanation": "DHCP server: Leases network configuration to clients.\nDNS server: Answers name-resolution queries using authoritative data or recursive resolution.\nFile server: Provides shared file access subject to permissions and protocol settings.\nPrint server: Coordinates shared printing, queues, and client access to printers.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-2.4", "title": "Configure a host network", "core": 1, "objective": "2.4", "domain": 2, "type": "network", "requires": ["core1-2.3"], "lore": "Address, prefix, gateway, and resolver settings must agree with the network design. Automatic assignment simplifies management but does not eliminate misconfiguration.\n\nYOUR TOOLKIT\n\nSubnet mask — A value identifying the network and host portions of an IPv4 address.\n\nDefault gateway — A router used to reach destinations outside the local subnet.\n\nPrivate address — An address from ranges intended for internal IPv4 use.\n\nDNS resolver setting — The configured service a client queries to resolve names.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A client has 169.254.x.x and cannot reach normal services. Check DHCP reachability and the connection rather than treating the link-local address as a valid routed lease.", "questions": [{"id": "core1-2.4-practice-2-4-0", "prompt": "Which concept best fits this description? A value identifying the network and host portions of an IPv4 address.", "options": ["DNS resolver setting", "Private address", "Subnet mask", "Default gateway"], "answer": 2, "explanation": "Subnet mask: A value identifying the network and host portions of an IPv4 address. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-2.4-practice-2-4-1", "prompt": "Which concept best fits this description? A router used to reach destinations outside the local subnet.", "options": ["DNS resolver setting", "Default gateway", "Private address", "Subnet mask"], "answer": 1, "explanation": "Default gateway: A router used to reach destinations outside the local subnet. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-2.4-match-2-4", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Subnet mask", "Default gateway", "Private address", "DNS resolver setting"], "options": ["An address from ranges intended for internal IPv4 use.", "A value identifying the network and host portions of an IPv4 address.", "The configured service a client queries to resolve names.", "A router used to reach destinations outside the local subnet."], "answer": [1, 3, 0, 2], "explanation": "Subnet mask: A value identifying the network and host portions of an IPv4 address.\nDefault gateway: A router used to reach destinations outside the local subnet.\nPrivate address: An address from ranges intended for internal IPv4 use.\nDNS resolver setting: The configured service a client queries to resolve names.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-2.5", "title": "Pick networking hardware by function", "core": 1, "objective": "2.5", "domain": 2, "type": "network", "requires": ["core1-2.4"], "lore": "Switches connect local endpoints, routers connect networks, access points bridge wireless clients, and modems adapt an access medium. Consumer devices may combine these roles.\n\nYOUR TOOLKIT\n\nSwitch — A local frame-forwarding device using a learned MAC table.\n\nRouter — A device forwarding packets between IP networks.\n\nWireless access point — A device connecting wireless stations to an appropriate distribution network.\n\nModem — An interface adapting signaling for a particular provider access technology.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A wired LAN works but has no wireless coverage. Add or configure an access-point function rather than buying an unrelated storage adapter.", "questions": [{"id": "core1-2.5-practice-2-5-0", "prompt": "Which concept best fits this description? A local frame-forwarding device using a learned MAC table.", "options": ["Modem", "Wireless access point", "Switch", "Router"], "answer": 2, "explanation": "Switch: A local frame-forwarding device using a learned MAC table. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-2.5-practice-2-5-1", "prompt": "Which concept best fits this description? A device forwarding packets between IP networks.", "options": ["Modem", "Router", "Wireless access point", "Switch"], "answer": 1, "explanation": "Router: A device forwarding packets between IP networks. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-2.5-match-2-5", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Switch", "Router", "Wireless access point", "Modem"], "options": ["A device connecting wireless stations to an appropriate distribution network.", "A local frame-forwarding device using a learned MAC table.", "An interface adapting signaling for a particular provider access technology.", "A device forwarding packets between IP networks."], "answer": [1, 3, 0, 2], "explanation": "Switch: A local frame-forwarding device using a learned MAC table.\nRouter: A device forwarding packets between IP networks.\nWireless access point: A device connecting wireless stations to an appropriate distribution network.\nModem: An interface adapting signaling for a particular provider access technology.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-2.6", "title": "Set up a SOHO network", "core": 1, "objective": "2.6", "domain": 2, "type": "network", "requires": ["core1-2.5"], "lore": "Change default administrator credentials, update firmware, configure LAN addressing and DHCP, secure wireless, and separate guests. Back up settings and verify the required flows.\n\nYOUR TOOLKIT\n\nGuest isolation — Restricting guest clients from internal resources or other clients according to policy.\n\nDHCP scope — A configured pool and options used for address leases.\n\nPort forwarding — Mapping selected inbound traffic to an internal service, creating exposure that must be justified.\n\nFirmware update — Applying supported device software maintenance through a verified process.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A home office needs guests without access to business storage. Use an isolated guest network and verify the separation.", "questions": [{"id": "core1-2.6-practice-2-6-0", "prompt": "Which concept best fits this description? Restricting guest clients from internal resources or other clients according to policy.", "options": ["Firmware update", "Port forwarding", "Guest isolation", "DHCP scope"], "answer": 2, "explanation": "Guest isolation: Restricting guest clients from internal resources or other clients according to policy. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-2.6-practice-2-6-1", "prompt": "Which concept best fits this description? A configured pool and options used for address leases.", "options": ["Firmware update", "DHCP scope", "Port forwarding", "Guest isolation"], "answer": 1, "explanation": "DHCP scope: A configured pool and options used for address leases. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-2.6-match-2-6", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Guest isolation", "DHCP scope", "Port forwarding", "Firmware update"], "options": ["Mapping selected inbound traffic to an internal service, creating exposure that must be justified.", "Restricting guest clients from internal resources or other clients according to policy.", "Applying supported device software maintenance through a verified process.", "A configured pool and options used for address leases."], "answer": [1, 3, 0, 2], "explanation": "Guest isolation: Restricting guest clients from internal resources or other clients according to policy.\nDHCP scope: A configured pool and options used for address leases.\nPort forwarding: Mapping selected inbound traffic to an internal service, creating exposure that must be justified.\nFirmware update: Applying supported device software maintenance through a verified process.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-2.7", "title": "Compare connection types", "core": 1, "objective": "2.7", "domain": 2, "type": "network", "requires": ["core1-2.6"], "lore": "Coverage, latency, capacity, price, availability, and provider design influence an internet link. A nominal bandwidth number alone does not describe service quality.\n\nYOUR TOOLKIT\n\nFiber internet — Provider access using optical infrastructure with service-specific capacity and availability.\n\nCable internet — Broadband access delivered through a cable-provider network.\n\nCellular broadband — Internet access using a mobile carrier's radio network.\n\nSatellite internet — Access through satellite infrastructure with performance depending on the system and conditions.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A rural site cannot obtain cable or fiber. Compare cellular, fixed wireless, or satellite against coverage and latency needs.", "questions": [{"id": "core1-2.7-practice-2-7-0", "prompt": "Which concept best fits this description? Provider access using optical infrastructure with service-specific capacity and availability.", "options": ["Satellite internet", "Cellular broadband", "Fiber internet", "Cable internet"], "answer": 2, "explanation": "Fiber internet: Provider access using optical infrastructure with service-specific capacity and availability. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-2.7-practice-2-7-1", "prompt": "Which concept best fits this description? Broadband access delivered through a cable-provider network.", "options": ["Satellite internet", "Cable internet", "Cellular broadband", "Fiber internet"], "answer": 1, "explanation": "Cable internet: Broadband access delivered through a cable-provider network. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-2.7-match-2-7", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Fiber internet", "Cable internet", "Cellular broadband", "Satellite internet"], "options": ["Internet access using a mobile carrier's radio network.", "Provider access using optical infrastructure with service-specific capacity and availability.", "Access through satellite infrastructure with performance depending on the system and conditions.", "Broadband access delivered through a cable-provider network."], "answer": [1, 3, 0, 2], "explanation": "Fiber internet: Provider access using optical infrastructure with service-specific capacity and availability.\nCable internet: Broadband access delivered through a cable-provider network.\nCellular broadband: Internet access using a mobile carrier's radio network.\nSatellite internet: Access through satellite infrastructure with performance depending on the system and conditions.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-2.8", "title": "Use network tools purposefully", "core": 1, "objective": "2.8", "domain": 2, "type": "network", "requires": ["core1-2.7"], "lore": "Choose a tool for a question and stay within authorization. Physical cable checks and application connectivity tests reveal different layers.\n\nYOUR TOOLKIT\n\nCrimper — A tool attaching compatible modular connectors to cable under the correct wiring standard.\n\nPunchdown tool — A tool terminating conductors on suitable insulation-displacement connections.\n\nTone generator and probe — Tools tracing a cable among possible physical paths.\n\nCable tester — A device testing properties such as continuity and wire mapping.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A new wall jack is dead. Check patching and continuity before reinstalling the web browser.", "questions": [{"id": "core1-2.8-practice-2-8-0", "prompt": "Which concept best fits this description? A tool attaching compatible modular connectors to cable under the correct wiring standard.", "options": ["Cable tester", "Tone generator and probe", "Crimper", "Punchdown tool"], "answer": 2, "explanation": "Crimper: A tool attaching compatible modular connectors to cable under the correct wiring standard. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-2.8-practice-2-8-1", "prompt": "Which concept best fits this description? A tool terminating conductors on suitable insulation-displacement connections.", "options": ["Cable tester", "Punchdown tool", "Tone generator and probe", "Crimper"], "answer": 1, "explanation": "Punchdown tool: A tool terminating conductors on suitable insulation-displacement connections. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-2.8-match-2-8", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Crimper", "Punchdown tool", "Tone generator and probe", "Cable tester"], "options": ["Tools tracing a cable among possible physical paths.", "A tool attaching compatible modular connectors to cable under the correct wiring standard.", "A device testing properties such as continuity and wire mapping.", "A tool terminating conductors on suitable insulation-displacement connections."], "answer": [1, 3, 0, 2], "explanation": "Crimper: A tool attaching compatible modular connectors to cable under the correct wiring standard.\nPunchdown tool: A tool terminating conductors on suitable insulation-displacement connections.\nTone generator and probe: Tools tracing a cable among possible physical paths.\nCable tester: A device testing properties such as continuity and wire mapping.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-3.1", "title": "Match display capabilities", "core": 1, "objective": "3.1", "domain": 3, "type": "physical", "requires": [], "lore": "Check panel technology, resolution, refresh, connectors, power, and cabling. Match supported modes across display, adapter, and cable.\n\nYOUR TOOLKIT\n\nLCD — A display technology using a backlight and liquid-crystal elements.\n\nOLED — A display technology in which pixels emit light individually.\n\nNative resolution — The physical pixel matrix of a fixed-pixel display.\n\nRefresh rate — How often a display updates per second, subject to source and link support.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A display works at low resolution but drops at a high refresh rate. Check link bandwidth and cable capabilities.", "questions": [{"id": "core1-3.1-practice-3-1-0", "prompt": "Which concept best fits this description? A display technology using a backlight and liquid-crystal elements.", "options": ["Native resolution", "LCD", "OLED", "Refresh rate"], "answer": 1, "explanation": "LCD: A display technology using a backlight and liquid-crystal elements. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-3.1-practice-3-1-1", "prompt": "Which concept best fits this description? A display technology in which pixels emit light individually.", "options": ["OLED", "Native resolution", "LCD", "Refresh rate"], "answer": 0, "explanation": "OLED: A display technology in which pixels emit light individually. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-3.1-match-3-1", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["LCD", "OLED", "Native resolution", "Refresh rate"], "options": ["The physical pixel matrix of a fixed-pixel display.", "A display technology using a backlight and liquid-crystal elements.", "How often a display updates per second, subject to source and link support.", "A display technology in which pixels emit light individually."], "answer": [1, 3, 0, 2], "explanation": "LCD: A display technology using a backlight and liquid-crystal elements.\nOLED: A display technology in which pixels emit light individually.\nNative resolution: The physical pixel matrix of a fixed-pixel display.\nRefresh rate: How often a display updates per second, subject to source and link support.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-3.2", "title": "Identify cables and connectors", "core": 1, "objective": "3.2", "domain": 3, "type": "physical", "requires": ["core1-3.1"], "lore": "Match both electrical or optical function and connector compatibility. An adapter may change a connector without providing an active protocol conversion.\n\nYOUR TOOLKIT\n\nHDMI — A digital interface commonly carrying video and audio.\n\nDisplayPort — A digital display interface with capabilities depending on version and implementation.\n\nSATA — An interface used for compatible internal storage devices.\n\nUSB — A peripheral interconnect family with multiple connectors, speeds, and power capabilities.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A passive adapter cannot create a video signal absent from the source port. Confirm output support before buying another cable.", "questions": [{"id": "core1-3.2-practice-3-2-0", "prompt": "Which concept best fits this description? A digital interface commonly carrying video and audio.", "options": ["SATA", "HDMI", "DisplayPort", "USB"], "answer": 1, "explanation": "HDMI: A digital interface commonly carrying video and audio. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-3.2-practice-3-2-1", "prompt": "Which concept best fits this description? A digital display interface with capabilities depending on version and implementation.", "options": ["DisplayPort", "SATA", "HDMI", "USB"], "answer": 0, "explanation": "DisplayPort: A digital display interface with capabilities depending on version and implementation. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-3.2-match-3-2", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["HDMI", "DisplayPort", "SATA", "USB"], "options": ["An interface used for compatible internal storage devices.", "A digital interface commonly carrying video and audio.", "A peripheral interconnect family with multiple connectors, speeds, and power capabilities.", "A digital display interface with capabilities depending on version and implementation."], "answer": [1, 3, 0, 2], "explanation": "HDMI: A digital interface commonly carrying video and audio.\nDisplayPort: A digital display interface with capabilities depending on version and implementation.\nSATA: An interface used for compatible internal storage devices.\nUSB: A peripheral interconnect family with multiple connectors, speeds, and power capabilities.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-3.3", "title": "Install compatible memory", "core": 1, "objective": "3.3", "domain": 3, "type": "physical", "requires": ["core1-3.2"], "lore": "Match generation, form factor, capacity, speed support, and platform requirements. Power down and use appropriate ESD handling before installation.\n\nYOUR TOOLKIT\n\nDIMM — A desktop or server memory-module form factor.\n\nSO-DIMM — A smaller memory-module form factor used in many laptops and compact systems.\n\nECC memory — Memory with error-detection and correction capability requiring platform support.\n\nMemory channel — A processor-memory data path whose supported population affects performance and configuration.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A board supports DDR5 desktop modules. A DDR4 module is not a compatible substitute even if its advertised speed looks similar.", "questions": [{"id": "core1-3.3-practice-3-3-0", "prompt": "Which concept best fits this description? A desktop or server memory-module form factor.", "options": ["ECC memory", "DIMM", "SO-DIMM", "Memory channel"], "answer": 1, "explanation": "DIMM: A desktop or server memory-module form factor. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-3.3-practice-3-3-1", "prompt": "Which concept best fits this description? A smaller memory-module form factor used in many laptops and compact systems.", "options": ["SO-DIMM", "ECC memory", "DIMM", "Memory channel"], "answer": 0, "explanation": "SO-DIMM: A smaller memory-module form factor used in many laptops and compact systems. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-3.3-match-3-3", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["DIMM", "SO-DIMM", "ECC memory", "Memory channel"], "options": ["Memory with error-detection and correction capability requiring platform support.", "A desktop or server memory-module form factor.", "A processor-memory data path whose supported population affects performance and configuration.", "A smaller memory-module form factor used in many laptops and compact systems."], "answer": [1, 3, 0, 2], "explanation": "DIMM: A desktop or server memory-module form factor.\nSO-DIMM: A smaller memory-module form factor used in many laptops and compact systems.\nECC memory: Memory with error-detection and correction capability requiring platform support.\nMemory channel: A processor-memory data path whose supported population affects performance and configuration.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-3.4", "title": "Choose and protect storage", "core": 1, "objective": "3.4", "domain": 3, "type": "physical", "requires": ["core1-3.3"], "lore": "Capacity, latency, endurance, interface, form factor, and data value determine storage choices. RAID improves some availability cases but does not replace backup.\n\nYOUR TOOLKIT\n\nNVMe — A storage protocol designed for nonvolatile memory commonly operating over PCIe.\n\nSATA SSD — Solid-state storage using the SATA interface and its performance limits.\n\nRAID1 — Mirroring data across drives to tolerate certain drive failures.\n\nRAID5 — Striping with distributed parity that can tolerate one member failure under the array's operating conditions.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A mirrored pair reproduces an accidental deletion on both disks. Restore from an independent backup rather than expecting the mirror to preserve history.", "questions": [{"id": "core1-3.4-practice-3-4-0", "prompt": "Which concept best fits this description? A storage protocol designed for nonvolatile memory commonly operating over PCIe.", "options": ["RAID1", "NVMe", "SATA SSD", "RAID5"], "answer": 1, "explanation": "NVMe: A storage protocol designed for nonvolatile memory commonly operating over PCIe. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-3.4-practice-3-4-1", "prompt": "Which concept best fits this description? Solid-state storage using the SATA interface and its performance limits.", "options": ["SATA SSD", "RAID1", "NVMe", "RAID5"], "answer": 0, "explanation": "SATA SSD: Solid-state storage using the SATA interface and its performance limits. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-3.4-match-3-4", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["NVMe", "SATA SSD", "RAID1", "RAID5"], "options": ["Mirroring data across drives to tolerate certain drive failures.", "A storage protocol designed for nonvolatile memory commonly operating over PCIe.", "Striping with distributed parity that can tolerate one member failure under the array's operating conditions.", "Solid-state storage using the SATA interface and its performance limits."], "answer": [1, 3, 0, 2], "explanation": "NVMe: A storage protocol designed for nonvolatile memory commonly operating over PCIe.\nSATA SSD: Solid-state storage using the SATA interface and its performance limits.\nRAID1: Mirroring data across drives to tolerate certain drive failures.\nRAID5: Striping with distributed parity that can tolerate one member failure under the array's operating conditions.", "tier": 2}, {"id": "core1-3.4-scenario-3-4-0", "prompt": "A user deletes a project from a healthy RAID1 array. The deletion appears on both members.\n\nWhy did the second member not preserve the file?", "options": ["RAID1 never stores files", "The display is too slow", "Mirroring copies changes, including deletion"], "answer": 2, "explanation": "Mirroring provides redundancy for some failures, not independent file history.", "tier": 3}, {"id": "core1-3.4-scenario-3-4-1", "prompt": "A user deletes a project from a healthy RAID1 array. The deletion appears on both members.\n\nWhere should you look for recovery?", "options": ["An independent backup or supported version-history copy", "The monitor cable", "A faster network adapter"], "answer": 0, "explanation": "Recovery requires a preserved prior copy.", "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-3.5", "title": "Build a compatible platform", "core": 1, "objective": "3.5", "domain": 3, "type": "physical", "requires": ["core1-3.4"], "lore": "CPU socket, chipset, firmware, memory, expansion, cooling, and chassis all constrain a build. Confirm compatibility from authoritative model documentation.\n\nYOUR TOOLKIT\n\nCPU socket — The physical and electrical processor interface requiring platform compatibility.\n\nUEFI — Modern platform firmware providing hardware initialization and boot services.\n\nPCIe — A serial expansion interconnect with lane and generation compatibility considerations.\n\nCooling system — Components transferring heat away from parts to maintain safe operating temperature.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A physically similar CPU may still be unsupported by a board's firmware. Check the support list and required firmware revision.", "questions": [{"id": "core1-3.5-practice-3-5-0", "prompt": "Which concept best fits this description? The physical and electrical processor interface requiring platform compatibility.", "options": ["PCIe", "CPU socket", "UEFI", "Cooling system"], "answer": 1, "explanation": "CPU socket: The physical and electrical processor interface requiring platform compatibility. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-3.5-practice-3-5-1", "prompt": "Which concept best fits this description? Modern platform firmware providing hardware initialization and boot services.", "options": ["UEFI", "PCIe", "CPU socket", "Cooling system"], "answer": 0, "explanation": "UEFI: Modern platform firmware providing hardware initialization and boot services. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-3.5-match-3-5", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["CPU socket", "UEFI", "PCIe", "Cooling system"], "options": ["A serial expansion interconnect with lane and generation compatibility considerations.", "The physical and electrical processor interface requiring platform compatibility.", "Components transferring heat away from parts to maintain safe operating temperature.", "Modern platform firmware providing hardware initialization and boot services."], "answer": [1, 3, 0, 2], "explanation": "CPU socket: The physical and electrical processor interface requiring platform compatibility.\nUEFI: Modern platform firmware providing hardware initialization and boot services.\nPCIe: A serial expansion interconnect with lane and generation compatibility considerations.\nCooling system: Components transferring heat away from parts to maintain safe operating temperature.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-3.6", "title": "Size and connect power safely", "core": 1, "objective": "3.6", "domain": 3, "type": "physical", "requires": ["core1-3.5"], "lore": "Match wattage, connectors, form factor, efficiency, and input requirements. Do not open a power supply; hazardous energy can remain inside.\n\nYOUR TOOLKIT\n\nPSU capacity — The supported output power available under the unit's specified conditions.\n\nMotherboard power connector — A dedicated supply connection that must match the platform's required pinout.\n\nModular cable compatibility — Using only cables explicitly compatible with that PSU model rather than mixing similar connectors.\n\nPower efficiency — The ratio of useful DC output to electrical input under specified loads.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A GPU requires specific power connectors and adequate supply capacity. Do not substitute an unsupported adapter or assume nominal wattage proves compatibility.", "questions": [{"id": "core1-3.6-practice-3-6-0", "prompt": "Which concept best fits this description? The supported output power available under the unit's specified conditions.", "options": ["Modular cable compatibility", "PSU capacity", "Motherboard power connector", "Power efficiency"], "answer": 1, "explanation": "PSU capacity: The supported output power available under the unit's specified conditions. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-3.6-practice-3-6-1", "prompt": "Which concept best fits this description? A dedicated supply connection that must match the platform's required pinout.", "options": ["Motherboard power connector", "Modular cable compatibility", "PSU capacity", "Power efficiency"], "answer": 0, "explanation": "Motherboard power connector: A dedicated supply connection that must match the platform's required pinout. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-3.6-match-3-6", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["PSU capacity", "Motherboard power connector", "Modular cable compatibility", "Power efficiency"], "options": ["Using only cables explicitly compatible with that PSU model rather than mixing similar connectors.", "The supported output power available under the unit's specified conditions.", "The ratio of useful DC output to electrical input under specified loads.", "A dedicated supply connection that must match the platform's required pinout."], "answer": [1, 3, 0, 2], "explanation": "PSU capacity: The supported output power available under the unit's specified conditions.\nMotherboard power connector: A dedicated supply connection that must match the platform's required pinout.\nModular cable compatibility: Using only cables explicitly compatible with that PSU model rather than mixing similar connectors.\nPower efficiency: The ratio of useful DC output to electrical input under specified loads.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-3.7", "title": "Deploy printers securely", "core": 1, "objective": "3.7", "domain": 3, "type": "physical", "requires": ["core1-3.6"], "lore": "Choose the connection, supported driver, queue, permissions, and secure settings. A successful installation must include a real test print and intended user access.\n\nYOUR TOOLKIT\n\nPrint queue — A managed sequence of jobs waiting for printer processing.\n\nPrinter driver — Software translating application print requests into supported device behavior.\n\nDuplex printing — Printing on both sides when hardware and settings support it.\n\nSecure print release — Holding a job until an authorized user releases it at the device.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A shared printer has a default web-admin password. Change it and restrict management instead of assuming a print queue protects the device.", "questions": [{"id": "core1-3.7-practice-3-7-0", "prompt": "Which concept best fits this description? A managed sequence of jobs waiting for printer processing.", "options": ["Duplex printing", "Print queue", "Printer driver", "Secure print release"], "answer": 1, "explanation": "Print queue: A managed sequence of jobs waiting for printer processing. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-3.7-practice-3-7-1", "prompt": "Which concept best fits this description? Software translating application print requests into supported device behavior.", "options": ["Printer driver", "Duplex printing", "Print queue", "Secure print release"], "answer": 0, "explanation": "Printer driver: Software translating application print requests into supported device behavior. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-3.7-match-3-7", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Print queue", "Printer driver", "Duplex printing", "Secure print release"], "options": ["Printing on both sides when hardware and settings support it.", "A managed sequence of jobs waiting for printer processing.", "Holding a job until an authorized user releases it at the device.", "Software translating application print requests into supported device behavior."], "answer": [1, 3, 0, 2], "explanation": "Print queue: A managed sequence of jobs waiting for printer processing.\nPrinter driver: Software translating application print requests into supported device behavior.\nDuplex printing: Printing on both sides when hardware and settings support it.\nSecure print release: Holding a job until an authorized user releases it at the device.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-3.8", "title": "Maintain the print mechanism", "core": 1, "objective": "3.8", "domain": 3, "type": "physical", "requires": ["core1-3.7"], "lore": "Follow manufacturer procedures and safety precautions for the printer type. Laser fusers can be hot, and consumables differ across technologies.\n\nYOUR TOOLKIT\n\nLaser fuser — The heated component that bonds toner to paper.\n\nImaging drum — A component forming the electrostatic image used in laser printing.\n\nInkjet printhead — A component depositing liquid ink through nozzles.\n\nThermal printing — Printing using heat with compatible media or a ribbon depending on technology.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A repeating mark appears at a regular interval on laser output. Inspect the relevant imaging or roller components according to the service guide.", "questions": [{"id": "core1-3.8-practice-3-8-0", "prompt": "Which concept best fits this description? The heated component that bonds toner to paper.", "options": ["Inkjet printhead", "Laser fuser", "Imaging drum", "Thermal printing"], "answer": 1, "explanation": "Laser fuser: The heated component that bonds toner to paper. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-3.8-practice-3-8-1", "prompt": "Which concept best fits this description? A component forming the electrostatic image used in laser printing.", "options": ["Imaging drum", "Inkjet printhead", "Laser fuser", "Thermal printing"], "answer": 0, "explanation": "Imaging drum: A component forming the electrostatic image used in laser printing. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-3.8-match-3-8", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Laser fuser", "Imaging drum", "Inkjet printhead", "Thermal printing"], "options": ["A component depositing liquid ink through nozzles.", "The heated component that bonds toner to paper.", "Printing using heat with compatible media or a ribbon depending on technology.", "A component forming the electrostatic image used in laser printing."], "answer": [1, 3, 0, 2], "explanation": "Laser fuser: The heated component that bonds toner to paper.\nImaging drum: A component forming the electrostatic image used in laser printing.\nInkjet printhead: A component depositing liquid ink through nozzles.\nThermal printing: Printing using heat with compatible media or a ribbon depending on technology.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-4.1", "title": "Use virtualization with boundaries", "core": 1, "objective": "4.1", "domain": 4, "type": "software", "requires": [], "lore": "A guest is not an independent physical machine. CPU, RAM, disk, firmware features, virtual networking, and host limits shape behavior.\n\nYOUR TOOLKIT\n\nHypervisor — The virtualization layer managing guest execution and access to host resources.\n\nVM snapshot — A point-in-time state useful for some rollback cases but not a replacement for an independent backup.\n\nVirtual switch — A software networking component connecting virtual interfaces according to its configuration.\n\nResource allocation — Assigning guest CPU, memory, and storage within the physical host's limits.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A VM starts but cannot reach the LAN because its virtual network is host-only. Choose the intended network mode and test it.", "questions": [{"id": "core1-4.1-practice-4-1-0", "prompt": "Which concept best fits this description? The virtualization layer managing guest execution and access to host resources.", "options": ["Hypervisor", "VM snapshot", "Resource allocation", "Virtual switch"], "answer": 0, "explanation": "Hypervisor: The virtualization layer managing guest execution and access to host resources. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-4.1-practice-4-1-1", "prompt": "Which concept best fits this description? A point-in-time state useful for some rollback cases but not a replacement for an independent backup.", "options": ["Virtual switch", "Hypervisor", "Resource allocation", "VM snapshot"], "answer": 3, "explanation": "VM snapshot: A point-in-time state useful for some rollback cases but not a replacement for an independent backup. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-4.1-match-4-1", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Hypervisor", "VM snapshot", "Virtual switch", "Resource allocation"], "options": ["A software networking component connecting virtual interfaces according to its configuration.", "The virtualization layer managing guest execution and access to host resources.", "Assigning guest CPU, memory, and storage within the physical host's limits.", "A point-in-time state useful for some rollback cases but not a replacement for an independent backup."], "answer": [1, 3, 0, 2], "explanation": "Hypervisor: The virtualization layer managing guest execution and access to host resources.\nVM snapshot: A point-in-time state useful for some rollback cases but not a replacement for an independent backup.\nVirtual switch: A software networking component connecting virtual interfaces according to its configuration.\nResource allocation: Assigning guest CPU, memory, and storage within the physical host's limits.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-4.2", "title": "Compare cloud service models", "core": 1, "objective": "4.2", "domain": 4, "type": "software", "requires": ["core1-4.1"], "lore": "Distinguish who manages hardware, platform, application, identities, and data. Cloud delivery does not remove all customer responsibilities.\n\nYOUR TOOLKIT\n\nIaaS — A model supplying infrastructure while the customer manages guest systems and workloads.\n\nPaaS — A model supplying a managed application platform while the customer manages deployed code and relevant settings.\n\nSaaS — A model delivering a hosted application to its users.\n\nMeasured service — Resource consumption tracked or billed according to a service's usage model.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A browser-based office suite is SaaS. The provider runs the application, while your organization still controls users and sharing.", "questions": [{"id": "core1-4.2-practice-4-2-0", "prompt": "Which concept best fits this description? A model supplying infrastructure while the customer manages guest systems and workloads.", "options": ["IaaS", "PaaS", "Measured service", "SaaS"], "answer": 0, "explanation": "IaaS: A model supplying infrastructure while the customer manages guest systems and workloads. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-4.2-practice-4-2-1", "prompt": "Which concept best fits this description? A model supplying a managed application platform while the customer manages deployed code and relevant settings.", "options": ["SaaS", "IaaS", "Measured service", "PaaS"], "answer": 3, "explanation": "PaaS: A model supplying a managed application platform while the customer manages deployed code and relevant settings. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-4.2-match-4-2", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["IaaS", "PaaS", "SaaS", "Measured service"], "options": ["A model delivering a hosted application to its users.", "A model supplying infrastructure while the customer manages guest systems and workloads.", "Resource consumption tracked or billed according to a service's usage model.", "A model supplying a managed application platform while the customer manages deployed code and relevant settings."], "answer": [1, 3, 0, 2], "explanation": "IaaS: A model supplying infrastructure while the customer manages guest systems and workloads.\nPaaS: A model supplying a managed application platform while the customer manages deployed code and relevant settings.\nSaaS: A model delivering a hosted application to its users.\nMeasured service: Resource consumption tracked or billed according to a service's usage model.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-5.1", "title": "Diagnose board, memory, CPU, and power", "core": 1, "objective": "5.1", "domain": 5, "type": "physical", "requires": [], "lore": "Observe symptoms, isolate recent changes, check safe basics, and test a specific theory. Do not replace every component at once.\n\nYOUR TOOLKIT\n\nNo-power condition — A symptom in which the system shows no expected power response.\n\nPOST indication — A firmware startup code, beep, or LED pattern interpreted using model documentation.\n\nThermal shutdown — A protective shutdown associated with excessive temperature or cooling failure.\n\nMemory seating fault — A module connection problem that can prevent startup or cause instability.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A PC has no lights after a move. Verify the outlet, cable, switch, and external power path before removing the motherboard.", "questions": [{"id": "core1-5.1-practice-5-1-0", "prompt": "Which concept best fits this description? A symptom in which the system shows no expected power response.", "options": ["POST indication", "Memory seating fault", "Thermal shutdown", "No-power condition"], "answer": 3, "explanation": "No-power condition: A symptom in which the system shows no expected power response. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-5.1-practice-5-1-1", "prompt": "Which concept best fits this description? A firmware startup code, beep, or LED pattern interpreted using model documentation.", "options": ["No-power condition", "Memory seating fault", "POST indication", "Thermal shutdown"], "answer": 2, "explanation": "POST indication: A firmware startup code, beep, or LED pattern interpreted using model documentation. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-5.1-match-5-1", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["No-power condition", "POST indication", "Thermal shutdown", "Memory seating fault"], "options": ["A protective shutdown associated with excessive temperature or cooling failure.", "A symptom in which the system shows no expected power response.", "A module connection problem that can prevent startup or cause instability.", "A firmware startup code, beep, or LED pattern interpreted using model documentation."], "answer": [1, 3, 0, 2], "explanation": "No-power condition: A symptom in which the system shows no expected power response.\nPOST indication: A firmware startup code, beep, or LED pattern interpreted using model documentation.\nThermal shutdown: A protective shutdown associated with excessive temperature or cooling failure.\nMemory seating fault: A module connection problem that can prevent startup or cause instability.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-5.2", "title": "Protect data while diagnosing storage", "core": 1, "objective": "5.2", "domain": 5, "type": "physical", "requires": ["core1-5.1"], "lore": "Data preservation may be more urgent than restoring boot. Avoid unnecessary writes to a failing drive and follow recovery escalation policy.\n\nYOUR TOOLKIT\n\nSMART warning — A storage-health indicator that can suggest failure risk without guaranteeing an exact failure date.\n\nDegraded RAID — An array operating with reduced fault tolerance after a member or related failure.\n\nBoot-order error — Firmware attempting startup from an unintended or unavailable device.\n\nStorage interface fault — A connection, controller, or cable problem disrupting communication with a drive.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A drive clicks and disappears intermittently. Stop repeated stress testing and assess backup or recovery needs.", "questions": [{"id": "core1-5.2-practice-5-2-0", "prompt": "Which concept best fits this description? A storage-health indicator that can suggest failure risk without guaranteeing an exact failure date.", "options": ["Degraded RAID", "Storage interface fault", "Boot-order error", "SMART warning"], "answer": 3, "explanation": "SMART warning: A storage-health indicator that can suggest failure risk without guaranteeing an exact failure date. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-5.2-practice-5-2-1", "prompt": "Which concept best fits this description? An array operating with reduced fault tolerance after a member or related failure.", "options": ["SMART warning", "Storage interface fault", "Degraded RAID", "Boot-order error"], "answer": 2, "explanation": "Degraded RAID: An array operating with reduced fault tolerance after a member or related failure. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-5.2-match-5-2", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["SMART warning", "Degraded RAID", "Boot-order error", "Storage interface fault"], "options": ["Firmware attempting startup from an unintended or unavailable device.", "A storage-health indicator that can suggest failure risk without guaranteeing an exact failure date.", "A connection, controller, or cable problem disrupting communication with a drive.", "An array operating with reduced fault tolerance after a member or related failure."], "answer": [1, 3, 0, 2], "explanation": "SMART warning: A storage-health indicator that can suggest failure risk without guaranteeing an exact failure date.\nDegraded RAID: An array operating with reduced fault tolerance after a member or related failure.\nBoot-order error: Firmware attempting startup from an unintended or unavailable device.\nStorage interface fault: A connection, controller, or cable problem disrupting communication with a drive.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-5.3", "title": "Find the display failure boundary", "core": 1, "objective": "5.3", "domain": 5, "type": "physical", "requires": ["core1-5.2"], "lore": "Separate power, input selection, cable, source output, mode, and panel faults. Known-good substitution can localize the fault without destructive changes.\n\nYOUR TOOLKIT\n\nIncorrect input — The display listening to a connector different from the one carrying the source signal.\n\nBacklight fault — A failure in an LCD illumination path that may leave a faint image visible.\n\nArtifacting — Unexpected visual corruption that may originate from the GPU, memory, cable, or display.\n\nUnsupported display mode — A resolution or refresh combination the link or device cannot reliably handle.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "An external monitor says no signal. Confirm selected input and cable seating, then test a known-good source or display.", "questions": [{"id": "core1-5.3-practice-5-3-0", "prompt": "Which concept best fits this description? The display listening to a connector different from the one carrying the source signal.", "options": ["Backlight fault", "Unsupported display mode", "Artifacting", "Incorrect input"], "answer": 3, "explanation": "Incorrect input: The display listening to a connector different from the one carrying the source signal. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-5.3-practice-5-3-1", "prompt": "Which concept best fits this description? A failure in an LCD illumination path that may leave a faint image visible.", "options": ["Incorrect input", "Unsupported display mode", "Backlight fault", "Artifacting"], "answer": 2, "explanation": "Backlight fault: A failure in an LCD illumination path that may leave a faint image visible. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-5.3-match-5-3", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Incorrect input", "Backlight fault", "Artifacting", "Unsupported display mode"], "options": ["Unexpected visual corruption that may originate from the GPU, memory, cable, or display.", "The display listening to a connector different from the one carrying the source signal.", "A resolution or refresh combination the link or device cannot reliably handle.", "A failure in an LCD illumination path that may leave a faint image visible."], "answer": [1, 3, 0, 2], "explanation": "Incorrect input: The display listening to a connector different from the one carrying the source signal.\nBacklight fault: A failure in an LCD illumination path that may leave a faint image visible.\nArtifacting: Unexpected visual corruption that may originate from the GPU, memory, cable, or display.\nUnsupported display mode: A resolution or refresh combination the link or device cannot reliably handle.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-5.4", "title": "Diagnose mobile symptoms safely", "core": 1, "objective": "5.4", "domain": 5, "type": "physical", "requires": ["core1-5.3"], "lore": "Check battery, charging, heat, physical damage, wireless state, and settings before invasive repair. Escalate hazardous batteries and liquid damage appropriately.\n\nYOUR TOOLKIT\n\nBattery wear — Reduced usable battery capacity after aging and charge cycles.\n\nCharging-path fault — A problem with the power source, cable, port, or charging circuitry.\n\nLiquid damage — Contamination or corrosion risk requiring appropriate service handling.\n\nDigitizer fault — A problem in the touch-input sensing path distinct from display image generation.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A phone heats while charging with a damaged cable. Disconnect safely and inspect the power accessories rather than forcing another charging cycle.", "questions": [{"id": "core1-5.4-practice-5-4-0", "prompt": "Which concept best fits this description? Reduced usable battery capacity after aging and charge cycles.", "options": ["Charging-path fault", "Digitizer fault", "Liquid damage", "Battery wear"], "answer": 3, "explanation": "Battery wear: Reduced usable battery capacity after aging and charge cycles. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-5.4-practice-5-4-1", "prompt": "Which concept best fits this description? A problem with the power source, cable, port, or charging circuitry.", "options": ["Battery wear", "Digitizer fault", "Charging-path fault", "Liquid damage"], "answer": 2, "explanation": "Charging-path fault: A problem with the power source, cable, port, or charging circuitry. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-5.4-match-5-4", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Battery wear", "Charging-path fault", "Liquid damage", "Digitizer fault"], "options": ["Contamination or corrosion risk requiring appropriate service handling.", "Reduced usable battery capacity after aging and charge cycles.", "A problem in the touch-input sensing path distinct from display image generation.", "A problem with the power source, cable, port, or charging circuitry."], "answer": [1, 3, 0, 2], "explanation": "Battery wear: Reduced usable battery capacity after aging and charge cycles.\nCharging-path fault: A problem with the power source, cable, port, or charging circuitry.\nLiquid damage: Contamination or corrosion risk requiring appropriate service handling.\nDigitizer fault: A problem in the touch-input sensing path distinct from display image generation.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-5.5", "title": "Locate the network symptom", "core": 1, "objective": "5.5", "domain": 5, "type": "physical", "requires": ["core1-5.4"], "lore": "Test scope, link, configuration, local reachability, gateway, name resolution, and application service. A Wi-Fi icon alone does not prove internet access.\n\nYOUR TOOLKIT\n\nLimited connectivity — A connection with only partial network function requiring layer-specific diagnosis.\n\nInterference — Competing radio energy degrading wireless reception or throughput.\n\nCaptive portal — A network access page requiring an action before normal connectivity is permitted.\n\nAddress conflict — Multiple devices using the same address and disrupting delivery.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A laptop reaches the gateway and an IP address but not a hostname. Test configured DNS and resolution.", "questions": [{"id": "core1-5.5-practice-5-5-0", "prompt": "Which concept best fits this description? A connection with only partial network function requiring layer-specific diagnosis.", "options": ["Interference", "Address conflict", "Captive portal", "Limited connectivity"], "answer": 3, "explanation": "Limited connectivity: A connection with only partial network function requiring layer-specific diagnosis. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-5.5-practice-5-5-1", "prompt": "Which concept best fits this description? Competing radio energy degrading wireless reception or throughput.", "options": ["Limited connectivity", "Address conflict", "Interference", "Captive portal"], "answer": 2, "explanation": "Interference: Competing radio energy degrading wireless reception or throughput. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-5.5-match-5-5", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Limited connectivity", "Interference", "Captive portal", "Address conflict"], "options": ["A network access page requiring an action before normal connectivity is permitted.", "A connection with only partial network function requiring layer-specific diagnosis.", "Multiple devices using the same address and disrupting delivery.", "Competing radio energy degrading wireless reception or throughput."], "answer": [1, 3, 0, 2], "explanation": "Limited connectivity: A connection with only partial network function requiring layer-specific diagnosis.\nInterference: Competing radio energy degrading wireless reception or throughput.\nCaptive portal: A network access page requiring an action before normal connectivity is permitted.\nAddress conflict: Multiple devices using the same address and disrupting delivery.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core1-5.6", "title": "Troubleshoot printing by stage", "core": 1, "objective": "5.6", "domain": 5, "type": "physical", "requires": ["core1-5.5"], "lore": "Separate connectivity, queue, driver, paper path, consumables, and imaging. Use device tests to distinguish a printer fault from a host-side job problem.\n\nYOUR TOOLKIT\n\nStuck print job — A queued job preventing normal processing and needing controlled queue remediation.\n\nPaper-feed fault — A problem in pickup, separation, alignment, or transport of media.\n\nLow consumable — Insufficient toner, ink, ribbon, or suitable media affecting output.\n\nDriver mismatch — An incompatible translation path causing incorrect or failed printed output.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "The printer's internal test page is clean but one application's output is garbled. Investigate the application or driver path before replacing the fuser.", "questions": [{"id": "core1-5.6-practice-5-6-0", "prompt": "Which concept best fits this description? A queued job preventing normal processing and needing controlled queue remediation.", "options": ["Paper-feed fault", "Driver mismatch", "Low consumable", "Stuck print job"], "answer": 3, "explanation": "Stuck print job: A queued job preventing normal processing and needing controlled queue remediation. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-5.6-practice-5-6-1", "prompt": "Which concept best fits this description? A problem in pickup, separation, alignment, or transport of media.", "options": ["Stuck print job", "Driver mismatch", "Paper-feed fault", "Low consumable"], "answer": 2, "explanation": "Paper-feed fault: A problem in pickup, separation, alignment, or transport of media. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core1-5.6-match-5-6", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Stuck print job", "Paper-feed fault", "Low consumable", "Driver mismatch"], "options": ["Insufficient toner, ink, ribbon, or suitable media affecting output.", "A queued job preventing normal processing and needing controlled queue remediation.", "An incompatible translation path causing incorrect or failed printed output.", "A problem in pickup, separation, alignment, or transport of media."], "answer": [1, 3, 0, 2], "explanation": "Stuck print job: A queued job preventing normal processing and needing controlled queue remediation.\nPaper-feed fault: A problem in pickup, separation, alignment, or transport of media.\nLow consumable: Insufficient toner, ink, ribbon, or suitable media affecting output.\nDriver mismatch: An incompatible translation path causing incorrect or failed printed output.", "tier": 2}, {"id": "core1-5.6-scenario-5-6-0", "prompt": "The printer's own test page is clean. One computer prints garbled output; another prints correctly.\n\nWhich boundary should you investigate first?", "options": ["The building's water supply", "The affected computer's application, driver, and queue", "The printer's fuser temperature only"], "answer": 1, "explanation": "A clean device test and a working second client narrow the problem toward the first client's path.", "tier": 3}, {"id": "core1-5.6-scenario-5-6-1", "prompt": "The printer's own test page is clean. One computer prints garbled output; another prints correctly.\n\nWhat is a useful validation after correction?", "options": ["Count paper sheets", "Reboot unrelated routers", "Print the original job from the affected client"], "answer": 2, "explanation": "Repeat the failing use case and verify expected output.", "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA 220-1201 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/34be017cb73211ef8985a6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-1.1", "title": "Choose the operating-system family", "core": 2, "objective": "1.1", "domain": 1, "type": "software", "requires": [], "lore": "Select an OS for application support, hardware compatibility, management, accessibility, and lifecycle needs. Support requirements matter as much as familiarity.\n\nYOUR TOOLKIT\n\nWindows — A Microsoft operating-system family commonly managed through local and organizational tools.\n\nmacOS — Apple's desktop operating system for supported Mac hardware.\n\nLinux — A family of operating systems built around the Linux kernel with distribution-specific tooling.\n\nMobile OS — A platform such as Android or iOS with device-specific application and management constraints.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A required business tool supports only a particular OS family. Verify vendor support before promising a different platform can run it natively.", "questions": [{"id": "core2-1.1-practice-1-1-0", "prompt": "Which concept best fits this description? A Microsoft operating-system family commonly managed through local and organizational tools.", "options": ["macOS", "Mobile OS", "Linux", "Windows"], "answer": 3, "explanation": "Windows: A Microsoft operating-system family commonly managed through local and organizational tools. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.1-practice-1-1-1", "prompt": "Which concept best fits this description? Apple's desktop operating system for supported Mac hardware.", "options": ["Windows", "Mobile OS", "macOS", "Linux"], "answer": 2, "explanation": "macOS: Apple's desktop operating system for supported Mac hardware. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.1-match-1-1", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Windows", "macOS", "Linux", "Mobile OS"], "options": ["A family of operating systems built around the Linux kernel with distribution-specific tooling.", "A Microsoft operating-system family commonly managed through local and organizational tools.", "A platform such as Android or iOS with device-specific application and management constraints.", "Apple's desktop operating system for supported Mac hardware."], "answer": [1, 3, 0, 2], "explanation": "Windows: A Microsoft operating-system family commonly managed through local and organizational tools.\nmacOS: Apple's desktop operating system for supported Mac hardware.\nLinux: A family of operating systems built around the Linux kernel with distribution-specific tooling.\nMobile OS: A platform such as Android or iOS with device-specific application and management constraints.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-1.2", "title": "Plan installation and upgrades", "core": 2, "objective": "1.2", "domain": 1, "type": "software", "requires": ["core2-1.1"], "lore": "Verify requirements, compatibility, licensing, backup, recovery keys, and application migration. An upgrade is not a backup strategy.\n\nYOUR TOOLKIT\n\nClean install — Installing an OS into a fresh target state rather than retaining the existing installation.\n\nIn-place upgrade — Replacing the OS version while attempting to preserve supported applications and settings.\n\nBoot media — A supported startup medium used to install or recover a system.\n\nPartition scheme — The disk organization approach such as GPT or MBR that must suit platform and boot requirements.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "Before replacing an OS, back up user data, verify recovery access, and confirm a tested rollback or restore route.", "questions": [{"id": "core2-1.2-practice-1-2-0", "prompt": "Which concept best fits this description? Installing an OS into a fresh target state rather than retaining the existing installation.", "options": ["In-place upgrade", "Partition scheme", "Boot media", "Clean install"], "answer": 3, "explanation": "Clean install: Installing an OS into a fresh target state rather than retaining the existing installation. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.2-practice-1-2-1", "prompt": "Which concept best fits this description? Replacing the OS version while attempting to preserve supported applications and settings.", "options": ["Clean install", "Partition scheme", "In-place upgrade", "Boot media"], "answer": 2, "explanation": "In-place upgrade: Replacing the OS version while attempting to preserve supported applications and settings. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.2-match-1-2", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Clean install", "In-place upgrade", "Boot media", "Partition scheme"], "options": ["A supported startup medium used to install or recover a system.", "Installing an OS into a fresh target state rather than retaining the existing installation.", "The disk organization approach such as GPT or MBR that must suit platform and boot requirements.", "Replacing the OS version while attempting to preserve supported applications and settings."], "answer": [1, 3, 0, 2], "explanation": "Clean install: Installing an OS into a fresh target state rather than retaining the existing installation.\nIn-place upgrade: Replacing the OS version while attempting to preserve supported applications and settings.\nBoot media: A supported startup medium used to install or recover a system.\nPartition scheme: The disk organization approach such as GPT or MBR that must suit platform and boot requirements.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-1.3", "title": "Match Windows editions to requirements", "core": 2, "objective": "1.3", "domain": 1, "type": "software", "requires": ["core2-1.2"], "lore": "Edition features and licensing determine management and deployment options. Check the current supported release rather than assuming every edition has the same capabilities.\n\nYOUR TOOLKIT\n\nDomain join — Connecting a supported Windows installation to an organizational identity and management domain.\n\nEdition feature set — Capabilities enabled by the licensed OS edition.\n\nHardware requirement — A minimum or supported component specification needed by an OS release.\n\nLifecycle support — The period and conditions under which an OS receives vendor maintenance.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A business requires organizational domain participation and managed security features. Verify the selected edition supports them before purchase.", "questions": [{"id": "core2-1.3-practice-1-3-0", "prompt": "Which concept best fits this description? Connecting a supported Windows installation to an organizational identity and management domain.", "options": ["Edition feature set", "Lifecycle support", "Hardware requirement", "Domain join"], "answer": 3, "explanation": "Domain join: Connecting a supported Windows installation to an organizational identity and management domain. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.3-practice-1-3-1", "prompt": "Which concept best fits this description? Capabilities enabled by the licensed OS edition.", "options": ["Domain join", "Lifecycle support", "Edition feature set", "Hardware requirement"], "answer": 2, "explanation": "Edition feature set: Capabilities enabled by the licensed OS edition. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.3-match-1-3", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Domain join", "Edition feature set", "Hardware requirement", "Lifecycle support"], "options": ["A minimum or supported component specification needed by an OS release.", "Connecting a supported Windows installation to an organizational identity and management domain.", "The period and conditions under which an OS receives vendor maintenance.", "Capabilities enabled by the licensed OS edition."], "answer": [1, 3, 0, 2], "explanation": "Domain join: Connecting a supported Windows installation to an organizational identity and management domain.\nEdition feature set: Capabilities enabled by the licensed OS edition.\nHardware requirement: A minimum or supported component specification needed by an OS release.\nLifecycle support: The period and conditions under which an OS receives vendor maintenance.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-1.4", "title": "Use Windows utilities as evidence", "core": 2, "objective": "1.4", "domain": 1, "type": "software", "requires": ["core2-1.3"], "lore": "Choose a utility that answers the question and use elevation only when required. Observe before changing configurations.\n\nYOUR TOOLKIT\n\nTask Manager — A utility for examining processes, resource use, and startup behavior.\n\nEvent Viewer — A tool for inspecting Windows event logs.\n\nDisk Management — A utility for inspecting and managing supported disk and volume configuration.\n\nDevice Manager — A utility for inspecting hardware devices, status, and drivers.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A service fails at startup. Event Viewer and service status can reveal a specific error before a reinstall is considered.", "questions": [{"id": "core2-1.4-practice-1-4-0", "prompt": "Which concept best fits this description? A utility for examining processes, resource use, and startup behavior.", "options": ["Event Viewer", "Device Manager", "Disk Management", "Task Manager"], "answer": 3, "explanation": "Task Manager: A utility for examining processes, resource use, and startup behavior. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.4-practice-1-4-1", "prompt": "Which concept best fits this description? A tool for inspecting Windows event logs.", "options": ["Task Manager", "Device Manager", "Event Viewer", "Disk Management"], "answer": 2, "explanation": "Event Viewer: A tool for inspecting Windows event logs. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.4-match-1-4", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Task Manager", "Event Viewer", "Disk Management", "Device Manager"], "options": ["A utility for inspecting and managing supported disk and volume configuration.", "A utility for examining processes, resource use, and startup behavior.", "A utility for inspecting hardware devices, status, and drivers.", "A tool for inspecting Windows event logs."], "answer": [1, 3, 0, 2], "explanation": "Task Manager: A utility for examining processes, resource use, and startup behavior.\nEvent Viewer: A tool for inspecting Windows event logs.\nDisk Management: A utility for inspecting and managing supported disk and volume configuration.\nDevice Manager: A utility for inspecting hardware devices, status, and drivers.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-1.5", "title": "Use commands with a purpose", "core": 2, "objective": "1.5", "domain": 1, "type": "software", "requires": ["core2-1.4"], "lore": "Understand scope and side effects before entering commands. Read output and distinguish network diagnosis from disk or system repair.\n\nYOUR TOOLKIT\n\nipconfig — A Windows command displaying IP configuration and supporting selected lease or resolver operations.\n\nping — A command testing ICMP response subject to routing and filtering.\n\nsfc — A Windows tool checking and repairing protected system files within its supported scope.\n\nchkdsk — A filesystem-checking tool whose options and repair implications must be understood before use.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A host has an unexpected gateway. Inspect ipconfig output first rather than deleting arbitrary system files.", "questions": [{"id": "core2-1.5-practice-1-5-0", "prompt": "Which concept best fits this description? A Windows command displaying IP configuration and supporting selected lease or resolver operations.", "options": ["ping", "chkdsk", "sfc", "ipconfig"], "answer": 3, "explanation": "ipconfig: A Windows command displaying IP configuration and supporting selected lease or resolver operations. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.5-practice-1-5-1", "prompt": "Which concept best fits this description? A command testing ICMP response subject to routing and filtering.", "options": ["ipconfig", "chkdsk", "ping", "sfc"], "answer": 2, "explanation": "ping: A command testing ICMP response subject to routing and filtering. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.5-match-1-5", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["ipconfig", "ping", "sfc", "chkdsk"], "options": ["A Windows tool checking and repairing protected system files within its supported scope.", "A Windows command displaying IP configuration and supporting selected lease or resolver operations.", "A filesystem-checking tool whose options and repair implications must be understood before use.", "A command testing ICMP response subject to routing and filtering."], "answer": [1, 3, 0, 2], "explanation": "ipconfig: A Windows command displaying IP configuration and supporting selected lease or resolver operations.\nping: A command testing ICMP response subject to routing and filtering.\nsfc: A Windows tool checking and repairing protected system files within its supported scope.\nchkdsk: A filesystem-checking tool whose options and repair implications must be understood before use.", "tier": 2}, {"id": "core2-1.5-scenario-1-5-0", "prompt": "Windows client: IPv4 192.0.2.15/24; gateway 192.0.2.254. Intended gateway per the approved design: 192.0.2.1.\n\nWhich command displays the current address configuration?", "options": ["ipconfig", "format", "sfc"], "answer": 0, "explanation": "ipconfig shows the relevant host network configuration.", "tier": 3}, {"id": "core2-1.5-scenario-1-5-1", "prompt": "Windows client: IPv4 192.0.2.15/24; gateway 192.0.2.254. Intended gateway per the approved design: 192.0.2.1.\n\nWhat should you do after an authorized gateway correction?", "options": ["Delete system logs", "Test local and remote access and document the result", "Disable every firewall rule"], "answer": 1, "explanation": "Verification checks that the correction solved the symptom without unrelated destructive changes.", "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-1.6", "title": "Configure Windows deliberately", "core": 2, "objective": "1.6", "domain": 1, "type": "software", "requires": ["core2-1.5"], "lore": "Settings control devices, updates, privacy, accessibility, accounts, and applications. Organizational policy can override a local preference.\n\nYOUR TOOLKIT\n\nWindows Update — The mechanism managing supported OS updates and related servicing.\n\nAccessibility settings — Options adapting input, output, or interaction to user needs.\n\nPrivacy settings — Controls governing selected data access and application permissions.\n\nDefault application — The configured handler for a file type, link, or supported action.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A user cannot change an update setting enforced by management. Identify the policy owner rather than repeatedly changing the same local toggle.", "questions": [{"id": "core2-1.6-practice-1-6-0", "prompt": "Which concept best fits this description? The mechanism managing supported OS updates and related servicing.", "options": ["Accessibility settings", "Default application", "Privacy settings", "Windows Update"], "answer": 3, "explanation": "Windows Update: The mechanism managing supported OS updates and related servicing. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.6-practice-1-6-1", "prompt": "Which concept best fits this description? Options adapting input, output, or interaction to user needs.", "options": ["Windows Update", "Default application", "Accessibility settings", "Privacy settings"], "answer": 2, "explanation": "Accessibility settings: Options adapting input, output, or interaction to user needs. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.6-match-1-6", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Windows Update", "Accessibility settings", "Privacy settings", "Default application"], "options": ["Controls governing selected data access and application permissions.", "The mechanism managing supported OS updates and related servicing.", "The configured handler for a file type, link, or supported action.", "Options adapting input, output, or interaction to user needs."], "answer": [1, 3, 0, 2], "explanation": "Windows Update: The mechanism managing supported OS updates and related servicing.\nAccessibility settings: Options adapting input, output, or interaction to user needs.\nPrivacy settings: Controls governing selected data access and application permissions.\nDefault application: The configured handler for a file type, link, or supported action.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-1.7", "title": "Configure Windows network access", "core": 2, "objective": "1.7", "domain": 1, "type": "software", "requires": ["core2-1.6"], "lore": "Separate address configuration, network profile, sharing, firewall, and remote access. A private network label is not a substitute for explicit access policy.\n\nYOUR TOOLKIT\n\nNetwork profile — A Windows classification influencing discovery and firewall policy behavior.\n\nSMB share — A file-sharing resource accessed through SMB under share and filesystem permissions.\n\nMapped drive — A client-side drive-letter reference to a network resource.\n\nWindows firewall rule — A configured allow or block policy for specified traffic and profiles.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A share works locally but not remotely. Verify name resolution, permissions, SMB access, and firewall scope.", "questions": [{"id": "core2-1.7-practice-1-7-0", "prompt": "Which concept best fits this description? A Windows classification influencing discovery and firewall policy behavior.", "options": ["SMB share", "Windows firewall rule", "Mapped drive", "Network profile"], "answer": 3, "explanation": "Network profile: A Windows classification influencing discovery and firewall policy behavior. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.7-practice-1-7-1", "prompt": "Which concept best fits this description? A file-sharing resource accessed through SMB under share and filesystem permissions.", "options": ["Network profile", "Windows firewall rule", "SMB share", "Mapped drive"], "answer": 2, "explanation": "SMB share: A file-sharing resource accessed through SMB under share and filesystem permissions. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.7-match-1-7", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Network profile", "SMB share", "Mapped drive", "Windows firewall rule"], "options": ["A client-side drive-letter reference to a network resource.", "A Windows classification influencing discovery and firewall policy behavior.", "A configured allow or block policy for specified traffic and profiles.", "A file-sharing resource accessed through SMB under share and filesystem permissions."], "answer": [1, 3, 0, 2], "explanation": "Network profile: A Windows classification influencing discovery and firewall policy behavior.\nSMB share: A file-sharing resource accessed through SMB under share and filesystem permissions.\nMapped drive: A client-side drive-letter reference to a network resource.\nWindows firewall rule: A configured allow or block policy for specified traffic and profiles.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-1.8", "title": "Support macOS workflows", "core": 2, "objective": "1.8", "domain": 1, "type": "software", "requires": ["core2-1.7"], "lore": "Use supported system tools, permissions, updates, and backups. Avoid assuming Windows paths or shortcuts behave identically on a Mac.\n\nYOUR TOOLKIT\n\nFinder — The macOS interface for browsing files and locations.\n\nTime Machine — Apple's backup mechanism for supported recovery workflows.\n\nKeychain — A macOS facility for managing credentials and related secrets.\n\nDisk Utility — A macOS utility for inspecting and managing supported disk structures.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A Mac needs recovery from a failed change. Check a usable Time Machine or other approved backup before modifying storage.", "questions": [{"id": "core2-1.8-practice-1-8-0", "prompt": "Which concept best fits this description? The macOS interface for browsing files and locations.", "options": ["Time Machine", "Disk Utility", "Keychain", "Finder"], "answer": 3, "explanation": "Finder: The macOS interface for browsing files and locations. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.8-practice-1-8-1", "prompt": "Which concept best fits this description? Apple's backup mechanism for supported recovery workflows.", "options": ["Finder", "Disk Utility", "Time Machine", "Keychain"], "answer": 2, "explanation": "Time Machine: Apple's backup mechanism for supported recovery workflows. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.8-match-1-8", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Finder", "Time Machine", "Keychain", "Disk Utility"], "options": ["A macOS facility for managing credentials and related secrets.", "The macOS interface for browsing files and locations.", "A macOS utility for inspecting and managing supported disk structures.", "Apple's backup mechanism for supported recovery workflows."], "answer": [1, 3, 0, 2], "explanation": "Finder: The macOS interface for browsing files and locations.\nTime Machine: Apple's backup mechanism for supported recovery workflows.\nKeychain: A macOS facility for managing credentials and related secrets.\nDisk Utility: A macOS utility for inspecting and managing supported disk structures.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-1.9", "title": "Navigate Linux safely", "core": 2, "objective": "1.9", "domain": 1, "type": "software", "requires": ["core2-1.8"], "lore": "Commands act within permissions and paths. Inspect targets carefully before changing ownership, permissions, services, or files, especially with elevation.\n\nYOUR TOOLKIT\n\nls — A command listing directory entries and optional metadata.\n\nchmod — A command modifying filesystem permission bits on supported files.\n\nsudo — A mechanism executing an authorized command under another identity, commonly with elevated privilege.\n\nPackage manager — A distribution tool managing software installation and updates from configured sources.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "An application cannot read a file. Check its path, owner, group, and permissions instead of granting universal write access.", "questions": [{"id": "core2-1.9-practice-1-9-0", "prompt": "Which concept best fits this description? A command listing directory entries and optional metadata.", "options": ["chmod", "Package manager", "sudo", "ls"], "answer": 3, "explanation": "ls: A command listing directory entries and optional metadata. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.9-practice-1-9-1", "prompt": "Which concept best fits this description? A command modifying filesystem permission bits on supported files.", "options": ["ls", "Package manager", "chmod", "sudo"], "answer": 2, "explanation": "chmod: A command modifying filesystem permission bits on supported files. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.9-match-1-9", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["ls", "chmod", "sudo", "Package manager"], "options": ["A mechanism executing an authorized command under another identity, commonly with elevated privilege.", "A command listing directory entries and optional metadata.", "A distribution tool managing software installation and updates from configured sources.", "A command modifying filesystem permission bits on supported files."], "answer": [1, 3, 0, 2], "explanation": "ls: A command listing directory entries and optional metadata.\nchmod: A command modifying filesystem permission bits on supported files.\nsudo: A mechanism executing an authorized command under another identity, commonly with elevated privilege.\nPackage manager: A distribution tool managing software installation and updates from configured sources.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-1.10", "title": "Install applications with compatibility in mind", "core": 2, "objective": "1.10", "domain": 1, "type": "software", "requires": ["core2-1.9"], "lore": "Check requirements, architecture, dependencies, licensing, trust, and organizational authorization. Preserve recovery options for business-critical applications.\n\nYOUR TOOLKIT\n\nApplication dependency — A required runtime, library, service, or component needed for software to function.\n\nArchitecture compatibility — Agreement between software requirements and the supported processor or operating-system architecture.\n\nTrusted installer — Software obtained through an authenticated approved source and verified as appropriate.\n\nInstallation authorization — Permission under organizational policy to deploy an application.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "An application requires a dependency and administrator installation. Obtain approval and a trusted installer rather than disabling endpoint controls.", "questions": [{"id": "core2-1.10-practice-1-10-0", "prompt": "Which concept best fits this description? A required runtime, library, service, or component needed for software to function.", "options": ["Architecture compatibility", "Installation authorization", "Trusted installer", "Application dependency"], "answer": 3, "explanation": "Application dependency: A required runtime, library, service, or component needed for software to function. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.10-practice-1-10-1", "prompt": "Which concept best fits this description? Agreement between software requirements and the supported processor or operating-system architecture.", "options": ["Application dependency", "Installation authorization", "Architecture compatibility", "Trusted installer"], "answer": 2, "explanation": "Architecture compatibility: Agreement between software requirements and the supported processor or operating-system architecture. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.10-match-1-10", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Application dependency", "Architecture compatibility", "Trusted installer", "Installation authorization"], "options": ["Software obtained through an authenticated approved source and verified as appropriate.", "A required runtime, library, service, or component needed for software to function.", "Permission under organizational policy to deploy an application.", "Agreement between software requirements and the supported processor or operating-system architecture."], "answer": [1, 3, 0, 2], "explanation": "Application dependency: A required runtime, library, service, or component needed for software to function.\nArchitecture compatibility: Agreement between software requirements and the supported processor or operating-system architecture.\nTrusted installer: Software obtained through an authenticated approved source and verified as appropriate.\nInstallation authorization: Permission under organizational policy to deploy an application.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-1.11", "title": "Support cloud productivity without oversharing", "core": 2, "objective": "1.11", "domain": 1, "type": "software", "requires": ["core2-1.10"], "lore": "Cloud collaboration combines identity, storage, synchronization, permissions, and licensing. Offline copies and online versions can diverge.\n\nYOUR TOOLKIT\n\nCollaboration permission — The allowed actions a user or link recipient may perform on shared content.\n\nCloud sync — Keeping selected local and hosted data in agreement under a service's conflict rules.\n\nVersion history — Recorded prior document states that may support review or recovery.\n\nLicense assignment — Allocating a service entitlement to the intended user or device.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A link lets anyone edit a confidential document. Restrict sharing and review existing access rather than assuming the cloud provider will infer intent.", "questions": [{"id": "core2-1.11-practice-1-11-0", "prompt": "Which concept best fits this description? The allowed actions a user or link recipient may perform on shared content.", "options": ["Cloud sync", "License assignment", "Version history", "Collaboration permission"], "answer": 3, "explanation": "Collaboration permission: The allowed actions a user or link recipient may perform on shared content. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.11-practice-1-11-1", "prompt": "Which concept best fits this description? Keeping selected local and hosted data in agreement under a service's conflict rules.", "options": ["Collaboration permission", "License assignment", "Cloud sync", "Version history"], "answer": 2, "explanation": "Cloud sync: Keeping selected local and hosted data in agreement under a service's conflict rules. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-1.11-match-1-11", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Collaboration permission", "Cloud sync", "Version history", "License assignment"], "options": ["Recorded prior document states that may support review or recovery.", "The allowed actions a user or link recipient may perform on shared content.", "Allocating a service entitlement to the intended user or device.", "Keeping selected local and hosted data in agreement under a service's conflict rules."], "answer": [1, 3, 0, 2], "explanation": "Collaboration permission: The allowed actions a user or link recipient may perform on shared content.\nCloud sync: Keeping selected local and hosted data in agreement under a service's conflict rules.\nVersion history: Recorded prior document states that may support review or recovery.\nLicense assignment: Allocating a service entitlement to the intended user or device.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-2.1", "title": "Layer security controls", "core": 2, "objective": "2.1", "domain": 2, "type": "security", "requires": [], "lore": "Physical, technical, and procedural safeguards work together. Select controls by the risk they reduce and verify that they are used correctly.\n\nYOUR TOOLKIT\n\nMFA — Authentication using distinct factor categories.\n\nLeast privilege — Access limited to the tasks a role actually needs.\n\nPhysical access control — Restrictions on entry to protected spaces or devices.\n\nSecurity awareness — Training and reinforcement helping users recognize and report risk.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A locked room protects equipment, but shared credentials still prevent accountable access. Solve both boundaries.", "questions": [{"id": "core2-2.1-practice-2-1-0", "prompt": "Which concept best fits this description? Authentication using distinct factor categories.", "options": ["Security awareness", "Physical access control", "MFA", "Least privilege"], "answer": 2, "explanation": "MFA: Authentication using distinct factor categories. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.1-practice-2-1-1", "prompt": "Which concept best fits this description? Access limited to the tasks a role actually needs.", "options": ["Security awareness", "Least privilege", "Physical access control", "MFA"], "answer": 1, "explanation": "Least privilege: Access limited to the tasks a role actually needs. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.1-match-2-1", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["MFA", "Least privilege", "Physical access control", "Security awareness"], "options": ["Restrictions on entry to protected spaces or devices.", "Authentication using distinct factor categories.", "Training and reinforcement helping users recognize and report risk.", "Access limited to the tasks a role actually needs."], "answer": [1, 3, 0, 2], "explanation": "MFA: Authentication using distinct factor categories.\nLeast privilege: Access limited to the tasks a role actually needs.\nPhysical access control: Restrictions on entry to protected spaces or devices.\nSecurity awareness: Training and reinforcement helping users recognize and report risk.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-2.2", "title": "Apply Windows security boundaries", "core": 2, "objective": "2.2", "domain": 2, "type": "security", "requires": ["core2-2.1"], "lore": "Protect accounts, files, storage, and network access. A local administrator can bypass many ordinary user restrictions, so minimize elevated use.\n\nYOUR TOOLKIT\n\nNTFS permissions — Filesystem access controls applied to objects on supported Windows volumes.\n\nUAC — A Windows mechanism mediating requests for elevated administrative actions.\n\nBitLocker — Windows volume encryption requiring supported configuration and protected recovery information.\n\nDefender protection — Windows security capabilities whose configuration and status should be managed and verified.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A standard user needs one approved installation. Use an authorized elevation workflow rather than granting permanent administrator rights.", "questions": [{"id": "core2-2.2-practice-2-2-0", "prompt": "Which concept best fits this description? Filesystem access controls applied to objects on supported Windows volumes.", "options": ["Defender protection", "BitLocker", "NTFS permissions", "UAC"], "answer": 2, "explanation": "NTFS permissions: Filesystem access controls applied to objects on supported Windows volumes. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.2-practice-2-2-1", "prompt": "Which concept best fits this description? A Windows mechanism mediating requests for elevated administrative actions.", "options": ["Defender protection", "UAC", "BitLocker", "NTFS permissions"], "answer": 1, "explanation": "UAC: A Windows mechanism mediating requests for elevated administrative actions. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.2-match-2-2", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["NTFS permissions", "UAC", "BitLocker", "Defender protection"], "options": ["Windows volume encryption requiring supported configuration and protected recovery information.", "Filesystem access controls applied to objects on supported Windows volumes.", "Windows security capabilities whose configuration and status should be managed and verified.", "A Windows mechanism mediating requests for elevated administrative actions."], "answer": [1, 3, 0, 2], "explanation": "NTFS permissions: Filesystem access controls applied to objects on supported Windows volumes.\nUAC: A Windows mechanism mediating requests for elevated administrative actions.\nBitLocker: Windows volume encryption requiring supported configuration and protected recovery information.\nDefender protection: Windows security capabilities whose configuration and status should be managed and verified.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-2.3", "title": "Secure wireless authentication", "core": 2, "objective": "2.3", "domain": 2, "type": "security", "requires": ["core2-2.2"], "lore": "Choose supported modern security and verify configuration across access point and client. Hiding an SSID is not strong authentication.\n\nYOUR TOOLKIT\n\nWPA2 — A wireless security generation commonly using AES-based protection in appropriate configurations.\n\nWPA3 — A newer wireless security generation with deployment and compatibility requirements.\n\n802.1X — Port-based authentication used in many enterprise wired and wireless access designs.\n\nPre-shared key — A shared wireless secret that creates revocation and distribution challenges as the user group grows.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "An office needs individual access revocation. Enterprise authentication is more manageable than a password shared by every employee.", "questions": [{"id": "core2-2.3-practice-2-3-0", "prompt": "Which concept best fits this description? A wireless security generation commonly using AES-based protection in appropriate configurations.", "options": ["Pre-shared key", "802.1X", "WPA2", "WPA3"], "answer": 2, "explanation": "WPA2: A wireless security generation commonly using AES-based protection in appropriate configurations. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.3-practice-2-3-1", "prompt": "Which concept best fits this description? A newer wireless security generation with deployment and compatibility requirements.", "options": ["Pre-shared key", "WPA3", "802.1X", "WPA2"], "answer": 1, "explanation": "WPA3: A newer wireless security generation with deployment and compatibility requirements. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.3-match-2-3", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["WPA2", "WPA3", "802.1X", "Pre-shared key"], "options": ["Port-based authentication used in many enterprise wired and wireless access designs.", "A wireless security generation commonly using AES-based protection in appropriate configurations.", "A shared wireless secret that creates revocation and distribution challenges as the user group grows.", "A newer wireless security generation with deployment and compatibility requirements."], "answer": [1, 3, 0, 2], "explanation": "WPA2: A wireless security generation commonly using AES-based protection in appropriate configurations.\nWPA3: A newer wireless security generation with deployment and compatibility requirements.\n802.1X: Port-based authentication used in many enterprise wired and wireless access designs.\nPre-shared key: A shared wireless secret that creates revocation and distribution challenges as the user group grows.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-2.4", "title": "Recognize malware behavior", "core": 2, "objective": "2.4", "domain": 2, "type": "security", "requires": ["core2-2.3"], "lore": "Identify behavior and preserve evidence before assuming a product name. One symptom can have benign causes, so correlate findings.\n\nYOUR TOOLKIT\n\nRansomware — Malware denying access to data or systems and commonly demanding payment.\n\nSpyware — Software collecting information without appropriate authorization.\n\nRootkit — Software concealing privileged activity or access.\n\nTrojan — Malicious functionality disguised as legitimate software.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A browser redirects and an unknown extension appeared recently. Investigate the extension and account state rather than immediately replacing hardware.", "questions": [{"id": "core2-2.4-practice-2-4-0", "prompt": "Which concept best fits this description? Malware denying access to data or systems and commonly demanding payment.", "options": ["Trojan", "Rootkit", "Ransomware", "Spyware"], "answer": 2, "explanation": "Ransomware: Malware denying access to data or systems and commonly demanding payment. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.4-practice-2-4-1", "prompt": "Which concept best fits this description? Software collecting information without appropriate authorization.", "options": ["Trojan", "Spyware", "Rootkit", "Ransomware"], "answer": 1, "explanation": "Spyware: Software collecting information without appropriate authorization. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.4-match-2-4", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Ransomware", "Spyware", "Rootkit", "Trojan"], "options": ["Software concealing privileged activity or access.", "Malware denying access to data or systems and commonly demanding payment.", "Malicious functionality disguised as legitimate software.", "Software collecting information without appropriate authorization."], "answer": [1, 3, 0, 2], "explanation": "Ransomware: Malware denying access to data or systems and commonly demanding payment.\nSpyware: Software collecting information without appropriate authorization.\nRootkit: Software concealing privileged activity or access.\nTrojan: Malicious functionality disguised as legitimate software.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-2.5", "title": "Recognize social engineering and weaknesses", "core": 2, "objective": "2.5", "domain": 2, "type": "security", "requires": ["core2-2.4"], "lore": "Attackers exploit trust, urgency, and access as well as technical flaws. Verify sensitive requests using a separately established channel.\n\nYOUR TOOLKIT\n\nPhishing — Deceptive messaging intended to trigger a harmful action.\n\nTailgating — Entering a controlled area by following an authorized person without proper authorization.\n\nImpersonation — Claiming a trusted identity to obtain access or cooperation.\n\nUnpatched vulnerability — A known weakness left without its applicable corrective maintenance.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "An unexpected caller requests an MFA code while claiming to be support. Refuse and verify through the known helpdesk route.", "questions": [{"id": "core2-2.5-practice-2-5-0", "prompt": "Which concept best fits this description? Deceptive messaging intended to trigger a harmful action.", "options": ["Unpatched vulnerability", "Impersonation", "Phishing", "Tailgating"], "answer": 2, "explanation": "Phishing: Deceptive messaging intended to trigger a harmful action. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.5-practice-2-5-1", "prompt": "Which concept best fits this description? Entering a controlled area by following an authorized person without proper authorization.", "options": ["Unpatched vulnerability", "Tailgating", "Impersonation", "Phishing"], "answer": 1, "explanation": "Tailgating: Entering a controlled area by following an authorized person without proper authorization. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.5-match-2-5", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Phishing", "Tailgating", "Impersonation", "Unpatched vulnerability"], "options": ["Claiming a trusted identity to obtain access or cooperation.", "Deceptive messaging intended to trigger a harmful action.", "A known weakness left without its applicable corrective maintenance.", "Entering a controlled area by following an authorized person without proper authorization."], "answer": [1, 3, 0, 2], "explanation": "Phishing: Deceptive messaging intended to trigger a harmful action.\nTailgating: Entering a controlled area by following an authorized person without proper authorization.\nImpersonation: Claiming a trusted identity to obtain access or cooperation.\nUnpatched vulnerability: A known weakness left without its applicable corrective maintenance.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-2.6", "title": "Remediate malware through a controlled process", "core": 2, "objective": "2.6", "domain": 2, "type": "security", "requires": ["core2-2.5"], "lore": "Assess and isolate affected systems, coordinate evidence needs, apply approved treatment, update protection, and verify before restoring access. Follow organizational incident policy.\n\nYOUR TOOLKIT\n\nQuarantine — Restricting an affected resource to limit harmful interaction.\n\nMalware removal — Eliminating identified malicious components through approved treatment.\n\nClean rebuild — Restoring a system from a known trusted baseline when required.\n\nPost-remediation verification — Checking that expected function and security are restored and persistence is absent.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A workstation is actively spreading malware. Use authorized containment and escalation before running unrelated cleanup tools.", "questions": [{"id": "core2-2.6-practice-2-6-0", "prompt": "Which concept best fits this description? Restricting an affected resource to limit harmful interaction.", "options": ["Post-remediation verification", "Clean rebuild", "Quarantine", "Malware removal"], "answer": 2, "explanation": "Quarantine: Restricting an affected resource to limit harmful interaction. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.6-practice-2-6-1", "prompt": "Which concept best fits this description? Eliminating identified malicious components through approved treatment.", "options": ["Post-remediation verification", "Malware removal", "Clean rebuild", "Quarantine"], "answer": 1, "explanation": "Malware removal: Eliminating identified malicious components through approved treatment. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.6-match-2-6", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Quarantine", "Malware removal", "Clean rebuild", "Post-remediation verification"], "options": ["Restoring a system from a known trusted baseline when required.", "Restricting an affected resource to limit harmful interaction.", "Checking that expected function and security are restored and persistence is absent.", "Eliminating identified malicious components through approved treatment."], "answer": [1, 3, 0, 2], "explanation": "Quarantine: Restricting an affected resource to limit harmful interaction.\nMalware removal: Eliminating identified malicious components through approved treatment.\nClean rebuild: Restoring a system from a known trusted baseline when required.\nPost-remediation verification: Checking that expected function and security are restored and persistence is absent.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-2.7", "title": "Harden a workstation", "core": 2, "objective": "2.7", "domain": 2, "type": "security", "requires": ["core2-2.6"], "lore": "Use supported software, updates, scoped accounts, screen locks, encryption, and limited services. Security requires maintenance after initial setup.\n\nYOUR TOOLKIT\n\nAutomatic screen lock — Requiring reauthentication after inactivity or an explicit lock.\n\nSecurity update — A supported correction for known software issues.\n\nApplication allowlist — An explicit permitted set of software identities or applications.\n\nAccount lifecycle — Provisioning, modification, and timely removal of access as responsibilities change.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A shared desk computer should lock automatically and use individual accounts rather than a universal logged-in session.", "questions": [{"id": "core2-2.7-practice-2-7-0", "prompt": "Which concept best fits this description? Requiring reauthentication after inactivity or an explicit lock.", "options": ["Account lifecycle", "Application allowlist", "Automatic screen lock", "Security update"], "answer": 2, "explanation": "Automatic screen lock: Requiring reauthentication after inactivity or an explicit lock. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.7-practice-2-7-1", "prompt": "Which concept best fits this description? A supported correction for known software issues.", "options": ["Account lifecycle", "Security update", "Application allowlist", "Automatic screen lock"], "answer": 1, "explanation": "Security update: A supported correction for known software issues. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.7-match-2-7", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Automatic screen lock", "Security update", "Application allowlist", "Account lifecycle"], "options": ["An explicit permitted set of software identities or applications.", "Requiring reauthentication after inactivity or an explicit lock.", "Provisioning, modification, and timely removal of access as responsibilities change.", "A supported correction for known software issues."], "answer": [1, 3, 0, 2], "explanation": "Automatic screen lock: Requiring reauthentication after inactivity or an explicit lock.\nSecurity update: A supported correction for known software issues.\nApplication allowlist: An explicit permitted set of software identities or applications.\nAccount lifecycle: Provisioning, modification, and timely removal of access as responsibilities change.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-2.8", "title": "Protect mobile data", "core": 2, "objective": "2.8", "domain": 2, "type": "security", "requires": ["core2-2.7"], "lore": "Use approved device management, encryption, updates, authentication, and remote recovery capabilities. Respect ownership and privacy boundaries.\n\nYOUR TOOLKIT\n\nRemote lock — An authorized command restricting access to a managed device.\n\nRemote wipe — An authorized removal of selected or all device data with consequences that must be understood.\n\nDevice encryption — Protecting stored mobile data using controlled cryptographic keys.\n\nRooting risk — Removing platform restrictions in a way that can undermine expected management and security controls.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A work phone is lost. Follow the reporting and approved remote-lock or wipe process while assessing exposure.", "questions": [{"id": "core2-2.8-practice-2-8-0", "prompt": "Which concept best fits this description? An authorized command restricting access to a managed device.", "options": ["Rooting risk", "Device encryption", "Remote lock", "Remote wipe"], "answer": 2, "explanation": "Remote lock: An authorized command restricting access to a managed device. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.8-practice-2-8-1", "prompt": "Which concept best fits this description? An authorized removal of selected or all device data with consequences that must be understood.", "options": ["Rooting risk", "Remote wipe", "Device encryption", "Remote lock"], "answer": 1, "explanation": "Remote wipe: An authorized removal of selected or all device data with consequences that must be understood. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.8-match-2-8", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Remote lock", "Remote wipe", "Device encryption", "Rooting risk"], "options": ["Protecting stored mobile data using controlled cryptographic keys.", "An authorized command restricting access to a managed device.", "Removing platform restrictions in a way that can undermine expected management and security controls.", "An authorized removal of selected or all device data with consequences that must be understood."], "answer": [1, 3, 0, 2], "explanation": "Remote lock: An authorized command restricting access to a managed device.\nRemote wipe: An authorized removal of selected or all device data with consequences that must be understood.\nDevice encryption: Protecting stored mobile data using controlled cryptographic keys.\nRooting risk: Removing platform restrictions in a way that can undermine expected management and security controls.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-2.9", "title": "Dispose of data appropriately", "core": 2, "objective": "2.9", "domain": 2, "type": "security", "requires": ["core2-2.8"], "lore": "Deleting a file is not always sanitization. Select a method based on medium, sensitivity, future use, and approved requirements, then verify completion.\n\nYOUR TOOLKIT\n\nClear — A sanitization class using logical techniques appropriate to the medium and intended recovery threat.\n\nPurge — A stronger sanitization class intended to make recovery infeasible using state-of-the-art laboratory techniques under the applicable method.\n\nDestroy — Rendering media unusable and data recovery infeasible through an appropriate physical process.\n\nDisposal record — Evidence identifying media, method, responsibility, and verification.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "An SSD leaves the organization. Use its approved sanitization method and verification rather than relying on a quick format.", "questions": [{"id": "core2-2.9-practice-2-9-0", "prompt": "Which concept best fits this description? A sanitization class using logical techniques appropriate to the medium and intended recovery threat.", "options": ["Disposal record", "Destroy", "Clear", "Purge"], "answer": 2, "explanation": "Clear: A sanitization class using logical techniques appropriate to the medium and intended recovery threat. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.9-practice-2-9-1", "prompt": "Which concept best fits this description? A stronger sanitization class intended to make recovery infeasible using state-of-the-art laboratory techniques under the applicable method.", "options": ["Disposal record", "Purge", "Destroy", "Clear"], "answer": 1, "explanation": "Purge: A stronger sanitization class intended to make recovery infeasible using state-of-the-art laboratory techniques under the applicable method. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.9-match-2-9", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Clear", "Purge", "Destroy", "Disposal record"], "options": ["Rendering media unusable and data recovery infeasible through an appropriate physical process.", "A sanitization class using logical techniques appropriate to the medium and intended recovery threat.", "Evidence identifying media, method, responsibility, and verification.", "A stronger sanitization class intended to make recovery infeasible using state-of-the-art laboratory techniques under the applicable method."], "answer": [1, 3, 0, 2], "explanation": "Clear: A sanitization class using logical techniques appropriate to the medium and intended recovery threat.\nPurge: A stronger sanitization class intended to make recovery infeasible using state-of-the-art laboratory techniques under the applicable method.\nDestroy: Rendering media unusable and data recovery infeasible through an appropriate physical process.\nDisposal record: Evidence identifying media, method, responsibility, and verification.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-2.10", "title": "Harden the small-office boundary", "core": 2, "objective": "2.10", "domain": 2, "type": "security", "requires": ["core2-2.9"], "lore": "Secure router administration, firmware, wireless, guest separation, and inbound exposure. Review settings after changes and backups after verification.\n\nYOUR TOOLKIT\n\nDefault credential change — Replacing supplied administrator secrets before routine deployment.\n\nGuest network — A separated access environment for visitors with limited internal reachability.\n\nInbound exposure — A reachable service created through direct addressing or forwarding that needs justification and controls.\n\nRouter configuration backup — A protected copy of known-good settings for controlled restoration.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A router exposes remote administration to the internet. Disable unnecessary exposure or restrict it through an approved secure access path.", "questions": [{"id": "core2-2.10-practice-2-10-0", "prompt": "Which concept best fits this description? Replacing supplied administrator secrets before routine deployment.", "options": ["Router configuration backup", "Inbound exposure", "Default credential change", "Guest network"], "answer": 2, "explanation": "Default credential change: Replacing supplied administrator secrets before routine deployment. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.10-practice-2-10-1", "prompt": "Which concept best fits this description? A separated access environment for visitors with limited internal reachability.", "options": ["Router configuration backup", "Guest network", "Inbound exposure", "Default credential change"], "answer": 1, "explanation": "Guest network: A separated access environment for visitors with limited internal reachability. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.10-match-2-10", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Default credential change", "Guest network", "Inbound exposure", "Router configuration backup"], "options": ["A reachable service created through direct addressing or forwarding that needs justification and controls.", "Replacing supplied administrator secrets before routine deployment.", "A protected copy of known-good settings for controlled restoration.", "A separated access environment for visitors with limited internal reachability."], "answer": [1, 3, 0, 2], "explanation": "Default credential change: Replacing supplied administrator secrets before routine deployment.\nGuest network: A separated access environment for visitors with limited internal reachability.\nInbound exposure: A reachable service created through direct addressing or forwarding that needs justification and controls.\nRouter configuration backup: A protected copy of known-good settings for controlled restoration.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-2.11", "title": "Protect the browser session", "core": 2, "objective": "2.11", "domain": 2, "type": "security", "requires": ["core2-2.10"], "lore": "Use supported updates, trusted extensions, appropriate privacy settings, and protected credential handling. A valid HTTPS certificate does not mean the site is honest.\n\nYOUR TOOLKIT\n\nBrowser extension review — Checking an add-on's source, necessity, permissions, and maintenance.\n\nCertificate warning — A trust or identity validation problem that should be investigated rather than routinely bypassed.\n\nPassword manager — An approved tool generating and storing unique credentials under controlled access.\n\nPop-up control — A browser setting limiting unsolicited windows while allowing justified exceptions.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A convincing phishing site has a valid certificate. Check the actual destination and request rather than trusting the padlock alone.", "questions": [{"id": "core2-2.11-practice-2-11-0", "prompt": "Which concept best fits this description? Checking an add-on's source, necessity, permissions, and maintenance.", "options": ["Pop-up control", "Password manager", "Browser extension review", "Certificate warning"], "answer": 2, "explanation": "Browser extension review: Checking an add-on's source, necessity, permissions, and maintenance. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.11-practice-2-11-1", "prompt": "Which concept best fits this description? A trust or identity validation problem that should be investigated rather than routinely bypassed.", "options": ["Pop-up control", "Certificate warning", "Password manager", "Browser extension review"], "answer": 1, "explanation": "Certificate warning: A trust or identity validation problem that should be investigated rather than routinely bypassed. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-2.11-match-2-11", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Browser extension review", "Certificate warning", "Password manager", "Pop-up control"], "options": ["An approved tool generating and storing unique credentials under controlled access.", "Checking an add-on's source, necessity, permissions, and maintenance.", "A browser setting limiting unsolicited windows while allowing justified exceptions.", "A trust or identity validation problem that should be investigated rather than routinely bypassed."], "answer": [1, 3, 0, 2], "explanation": "Browser extension review: Checking an add-on's source, necessity, permissions, and maintenance.\nCertificate warning: A trust or identity validation problem that should be investigated rather than routinely bypassed.\nPassword manager: An approved tool generating and storing unique credentials under controlled access.\nPop-up control: A browser setting limiting unsolicited windows while allowing justified exceptions.", "tier": 2}, {"id": "core2-2.11-scenario-2-11-0", "prompt": "A message links to a lookalike login site. Its HTTPS certificate validates for the lookalike name.\n\nWhat does the valid certificate establish?", "options": ["The company endorses the site", "The site cannot steal passwords", "The TLS identity matches that certified hostname under the trusted chain"], "answer": 2, "explanation": "TLS identity validation does not establish the site's honesty or the intended business destination.", "tier": 3}, {"id": "core2-2.11-scenario-2-11-1", "prompt": "A message links to a lookalike login site. Its HTTPS certificate validates for the lookalike name.\n\nWhat is the safer response?", "options": ["Use a known trusted route to the service and report the message", "Enter a password to see what happens", "Approve any MFA prompt it causes"], "answer": 0, "explanation": "Independent navigation and reporting avoid trusting the suspicious link.", "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-3.1", "title": "Diagnose Windows faults methodically", "core": 2, "objective": "3.1", "domain": 3, "type": "software", "requires": [], "lore": "Gather the exact error, timing, recent changes, and scope. Use appropriate logs and recovery options while preserving user data.\n\nYOUR TOOLKIT\n\nStop error — A serious Windows failure state requiring analysis of the specific code and context.\n\nStartup repair — A supported recovery workflow addressing certain boot problems.\n\nDriver rollback — Returning a device driver to a prior version when appropriate.\n\nSystem restore point — A recovery mechanism for selected system state that does not replace user-data backup.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A crash starts after a driver update. Evaluate rollback using a known-good supported driver rather than reinstalling every application.", "questions": [{"id": "core2-3.1-practice-3-1-0", "prompt": "Which concept best fits this description? A serious Windows failure state requiring analysis of the specific code and context.", "options": ["Driver rollback", "Stop error", "Startup repair", "System restore point"], "answer": 1, "explanation": "Stop error: A serious Windows failure state requiring analysis of the specific code and context. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-3.1-practice-3-1-1", "prompt": "Which concept best fits this description? A supported recovery workflow addressing certain boot problems.", "options": ["Startup repair", "Driver rollback", "Stop error", "System restore point"], "answer": 0, "explanation": "Startup repair: A supported recovery workflow addressing certain boot problems. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-3.1-match-3-1", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Stop error", "Startup repair", "Driver rollback", "System restore point"], "options": ["Returning a device driver to a prior version when appropriate.", "A serious Windows failure state requiring analysis of the specific code and context.", "A recovery mechanism for selected system state that does not replace user-data backup.", "A supported recovery workflow addressing certain boot problems."], "answer": [1, 3, 0, 2], "explanation": "Stop error: A serious Windows failure state requiring analysis of the specific code and context.\nStartup repair: A supported recovery workflow addressing certain boot problems.\nDriver rollback: Returning a device driver to a prior version when appropriate.\nSystem restore point: A recovery mechanism for selected system state that does not replace user-data backup.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-3.2", "title": "Diagnose mobile application faults", "core": 2, "objective": "3.2", "domain": 3, "type": "software", "requires": ["core2-3.1"], "lore": "Separate app state, permissions, storage, connectivity, OS compatibility, and account problems. Protect unsynchronized data before resets.\n\nYOUR TOOLKIT\n\nApp permission — An allowed capability such as camera or location access granted under the platform's model.\n\nStorage exhaustion — Insufficient available space causing updates or applications to fail.\n\nApp cache — Temporary application data that may be safely removable only under appropriate app-specific guidance.\n\nFactory reset — A destructive return to an initial device state requiring backup and account considerations.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "One application crashes while others work. Check its update, compatibility, and data state before factory-resetting the phone.", "questions": [{"id": "core2-3.2-practice-3-2-0", "prompt": "Which concept best fits this description? An allowed capability such as camera or location access granted under the platform's model.", "options": ["App cache", "App permission", "Storage exhaustion", "Factory reset"], "answer": 1, "explanation": "App permission: An allowed capability such as camera or location access granted under the platform's model. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-3.2-practice-3-2-1", "prompt": "Which concept best fits this description? Insufficient available space causing updates or applications to fail.", "options": ["Storage exhaustion", "App cache", "App permission", "Factory reset"], "answer": 0, "explanation": "Storage exhaustion: Insufficient available space causing updates or applications to fail. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-3.2-match-3-2", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["App permission", "Storage exhaustion", "App cache", "Factory reset"], "options": ["Temporary application data that may be safely removable only under appropriate app-specific guidance.", "An allowed capability such as camera or location access granted under the platform's model.", "A destructive return to an initial device state requiring backup and account considerations.", "Insufficient available space causing updates or applications to fail."], "answer": [1, 3, 0, 2], "explanation": "App permission: An allowed capability such as camera or location access granted under the platform's model.\nStorage exhaustion: Insufficient available space causing updates or applications to fail.\nApp cache: Temporary application data that may be safely removable only under appropriate app-specific guidance.\nFactory reset: A destructive return to an initial device state requiring backup and account considerations.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-3.3", "title": "Investigate mobile security symptoms", "core": 2, "objective": "3.3", "domain": 3, "type": "software", "requires": ["core2-3.2"], "lore": "Unexpected permissions, profiles, apps, traffic, and authentication events deserve investigation. Avoid declaring all battery drain malicious.\n\nYOUR TOOLKIT\n\nUnauthorized profile — A device configuration or management relationship installed without appropriate approval.\n\nSideloaded application — Software installed outside the normal approved app-distribution route.\n\nUnusual account session — An unfamiliar authenticated session that warrants identity and device review.\n\nDevice compromise escalation — Reporting suspected mobile compromise through the defined support or incident process.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "An unknown management profile appears on a personal phone. Verify its origin and seek approved support before entering more credentials.", "questions": [{"id": "core2-3.3-practice-3-3-0", "prompt": "Which concept best fits this description? A device configuration or management relationship installed without appropriate approval.", "options": ["Unusual account session", "Unauthorized profile", "Sideloaded application", "Device compromise escalation"], "answer": 1, "explanation": "Unauthorized profile: A device configuration or management relationship installed without appropriate approval. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-3.3-practice-3-3-1", "prompt": "Which concept best fits this description? Software installed outside the normal approved app-distribution route.", "options": ["Sideloaded application", "Unusual account session", "Unauthorized profile", "Device compromise escalation"], "answer": 0, "explanation": "Sideloaded application: Software installed outside the normal approved app-distribution route. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-3.3-match-3-3", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Unauthorized profile", "Sideloaded application", "Unusual account session", "Device compromise escalation"], "options": ["An unfamiliar authenticated session that warrants identity and device review.", "A device configuration or management relationship installed without appropriate approval.", "Reporting suspected mobile compromise through the defined support or incident process.", "Software installed outside the normal approved app-distribution route."], "answer": [1, 3, 0, 2], "explanation": "Unauthorized profile: A device configuration or management relationship installed without appropriate approval.\nSideloaded application: Software installed outside the normal approved app-distribution route.\nUnusual account session: An unfamiliar authenticated session that warrants identity and device review.\nDevice compromise escalation: Reporting suspected mobile compromise through the defined support or incident process.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-3.4", "title": "Investigate PC security faults", "core": 2, "objective": "3.4", "domain": 3, "type": "software", "requires": ["core2-3.3"], "lore": "Combine user reports, endpoint telemetry, account logs, and application changes. Contain confirmed harm and avoid destroying evidence prematurely.\n\nYOUR TOOLKIT\n\nBrowser hijack — Unauthorized alteration of browser behavior such as redirects or search settings.\n\nUnauthorized account change — A role, credential, recovery, or forwarding modification not approved by the owner or policy.\n\nEndpoint alert — A security finding requiring triage rather than automatic assumption of a confirmed incident.\n\nPersistence — A mechanism allowing unwanted access or code to survive normal restart or user activity.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "An account sends unexpected mail and has a new forwarding rule. Review sessions and mailbox rules, secure the identity, and escalate.", "questions": [{"id": "core2-3.4-practice-3-4-0", "prompt": "Which concept best fits this description? Unauthorized alteration of browser behavior such as redirects or search settings.", "options": ["Endpoint alert", "Browser hijack", "Unauthorized account change", "Persistence"], "answer": 1, "explanation": "Browser hijack: Unauthorized alteration of browser behavior such as redirects or search settings. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-3.4-practice-3-4-1", "prompt": "Which concept best fits this description? A role, credential, recovery, or forwarding modification not approved by the owner or policy.", "options": ["Unauthorized account change", "Endpoint alert", "Browser hijack", "Persistence"], "answer": 0, "explanation": "Unauthorized account change: A role, credential, recovery, or forwarding modification not approved by the owner or policy. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-3.4-match-3-4", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Browser hijack", "Unauthorized account change", "Endpoint alert", "Persistence"], "options": ["A security finding requiring triage rather than automatic assumption of a confirmed incident.", "Unauthorized alteration of browser behavior such as redirects or search settings.", "A mechanism allowing unwanted access or code to survive normal restart or user activity.", "A role, credential, recovery, or forwarding modification not approved by the owner or policy."], "answer": [1, 3, 0, 2], "explanation": "Browser hijack: Unauthorized alteration of browser behavior such as redirects or search settings.\nUnauthorized account change: A role, credential, recovery, or forwarding modification not approved by the owner or policy.\nEndpoint alert: A security finding requiring triage rather than automatic assumption of a confirmed incident.\nPersistence: A mechanism allowing unwanted access or code to survive normal restart or user activity.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-4.1", "title": "Leave a useful support record", "core": 2, "objective": "4.1", "domain": 4, "type": "software", "requires": [], "lore": "Document symptoms, scope, evidence, actions, approvals, and resolution in clear language. Protect sensitive information in tickets.\n\nYOUR TOOLKIT\n\nTicket prioritization — Assigning urgency and impact under the support process.\n\nKnowledge article — Reusable documented guidance for a known support need.\n\nAsset record — Information linking a device or service to ownership and configuration.\n\nEscalation note — A concise handoff describing evidence, attempted actions, and the help required.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A future technician should be able to understand why a setting changed without reading private credentials.", "questions": [{"id": "core2-4.1-practice-4-1-0", "prompt": "Which concept best fits this description? Assigning urgency and impact under the support process.", "options": ["Ticket prioritization", "Knowledge article", "Escalation note", "Asset record"], "answer": 0, "explanation": "Ticket prioritization: Assigning urgency and impact under the support process. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-4.1-practice-4-1-1", "prompt": "Which concept best fits this description? Reusable documented guidance for a known support need.", "options": ["Asset record", "Ticket prioritization", "Escalation note", "Knowledge article"], "answer": 3, "explanation": "Knowledge article: Reusable documented guidance for a known support need. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-4.1-match-4-1", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Ticket prioritization", "Knowledge article", "Asset record", "Escalation note"], "options": ["Information linking a device or service to ownership and configuration.", "Assigning urgency and impact under the support process.", "A concise handoff describing evidence, attempted actions, and the help required.", "Reusable documented guidance for a known support need."], "answer": [1, 3, 0, 2], "explanation": "Ticket prioritization: Assigning urgency and impact under the support process.\nKnowledge article: Reusable documented guidance for a known support need.\nAsset record: Information linking a device or service to ownership and configuration.\nEscalation note: A concise handoff describing evidence, attempted actions, and the help required.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-4.2", "title": "Change systems with accountability", "core": 2, "objective": "4.2", "domain": 4, "type": "software", "requires": ["core2-4.1"], "lore": "Assess impact, obtain approval, test, plan rollback, communicate, implement, and verify. Emergency work still needs an accountable process.\n\nYOUR TOOLKIT\n\nChange request — A documented proposal with purpose, scope, risk, and ownership.\n\nRollback plan — A usable way to return to an acceptable state if verification fails.\n\nMaintenance window — An agreed time for potentially disruptive work.\n\nPost-change verification — Confirming required functionality and recording the deployed result.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A change affects the only payroll workstation during processing. Coordinate timing and recovery rather than making a surprise edit.", "questions": [{"id": "core2-4.2-practice-4-2-0", "prompt": "Which concept best fits this description? A documented proposal with purpose, scope, risk, and ownership.", "options": ["Change request", "Rollback plan", "Post-change verification", "Maintenance window"], "answer": 0, "explanation": "Change request: A documented proposal with purpose, scope, risk, and ownership. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-4.2-practice-4-2-1", "prompt": "Which concept best fits this description? A usable way to return to an acceptable state if verification fails.", "options": ["Maintenance window", "Change request", "Post-change verification", "Rollback plan"], "answer": 3, "explanation": "Rollback plan: A usable way to return to an acceptable state if verification fails. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-4.2-match-4-2", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Change request", "Rollback plan", "Maintenance window", "Post-change verification"], "options": ["An agreed time for potentially disruptive work.", "A documented proposal with purpose, scope, risk, and ownership.", "Confirming required functionality and recording the deployed result.", "A usable way to return to an acceptable state if verification fails."], "answer": [1, 3, 0, 2], "explanation": "Change request: A documented proposal with purpose, scope, risk, and ownership.\nRollback plan: A usable way to return to an acceptable state if verification fails.\nMaintenance window: An agreed time for potentially disruptive work.\nPost-change verification: Confirming required functionality and recording the deployed result.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-4.3", "title": "Prove backup and recovery", "core": 2, "objective": "4.3", "domain": 4, "type": "software", "requires": ["core2-4.2"], "lore": "Choose copies and frequency based on data-loss and restoration needs. Verify recoverability and protect backup access independently.\n\nYOUR TOOLKIT\n\nFull backup — A copy of all selected data within the backup's defined scope.\n\nIncremental backup — A copy of changes since the preceding relevant backup under the backup system's chain rules.\n\nDifferential backup — A copy of changes since the last full backup.\n\nRestore test — A practical recovery exercise demonstrating that required data and services can be recovered.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A cloud-synced folder is deleted everywhere. Synchronization alone was not a complete independent recovery strategy.", "questions": [{"id": "core2-4.3-practice-4-3-0", "prompt": "Which concept best fits this description? A copy of all selected data within the backup's defined scope.", "options": ["Full backup", "Incremental backup", "Restore test", "Differential backup"], "answer": 0, "explanation": "Full backup: A copy of all selected data within the backup's defined scope. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-4.3-practice-4-3-1", "prompt": "Which concept best fits this description? A copy of changes since the preceding relevant backup under the backup system's chain rules.", "options": ["Differential backup", "Full backup", "Restore test", "Incremental backup"], "answer": 3, "explanation": "Incremental backup: A copy of changes since the preceding relevant backup under the backup system's chain rules. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-4.3-match-4-3", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Full backup", "Incremental backup", "Differential backup", "Restore test"], "options": ["A copy of changes since the last full backup.", "A copy of all selected data within the backup's defined scope.", "A practical recovery exercise demonstrating that required data and services can be recovered.", "A copy of changes since the preceding relevant backup under the backup system's chain rules."], "answer": [1, 3, 0, 2], "explanation": "Full backup: A copy of all selected data within the backup's defined scope.\nIncremental backup: A copy of changes since the preceding relevant backup under the backup system's chain rules.\nDifferential backup: A copy of changes since the last full backup.\nRestore test: A practical recovery exercise demonstrating that required data and services can be recovered.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-4.4", "title": "Work safely around equipment", "core": 2, "objective": "4.4", "domain": 4, "type": "software", "requires": ["core2-4.3"], "lore": "Power down where required, use ESD precautions, lift appropriately, and recognize components that need trained service. Never open a PSU or hazardous display assembly casually.\n\nYOUR TOOLKIT\n\nESD wrist strap — An appropriately used grounding aid for handling sensitive unpowered components under safe conditions.\n\nPower isolation — Removing relevant energy sources before work according to service instructions.\n\nLifting safety — Using suitable posture, assistance, or equipment for heavy hardware.\n\nHazard escalation — Stopping work and obtaining qualified help for risks outside the technician's authorization or training.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A damaged power supply has an internal fault. Replace or escalate according to procedure instead of opening its enclosure.", "questions": [{"id": "core2-4.4-practice-4-4-0", "prompt": "Which concept best fits this description? An appropriately used grounding aid for handling sensitive unpowered components under safe conditions.", "options": ["ESD wrist strap", "Power isolation", "Hazard escalation", "Lifting safety"], "answer": 0, "explanation": "ESD wrist strap: An appropriately used grounding aid for handling sensitive unpowered components under safe conditions. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-4.4-practice-4-4-1", "prompt": "Which concept best fits this description? Removing relevant energy sources before work according to service instructions.", "options": ["Lifting safety", "ESD wrist strap", "Hazard escalation", "Power isolation"], "answer": 3, "explanation": "Power isolation: Removing relevant energy sources before work according to service instructions. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-4.4-match-4-4", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["ESD wrist strap", "Power isolation", "Lifting safety", "Hazard escalation"], "options": ["Using suitable posture, assistance, or equipment for heavy hardware.", "An appropriately used grounding aid for handling sensitive unpowered components under safe conditions.", "Stopping work and obtaining qualified help for risks outside the technician's authorization or training.", "Removing relevant energy sources before work according to service instructions."], "answer": [1, 3, 0, 2], "explanation": "ESD wrist strap: An appropriately used grounding aid for handling sensitive unpowered components under safe conditions.\nPower isolation: Removing relevant energy sources before work according to service instructions.\nLifting safety: Using suitable posture, assistance, or equipment for heavy hardware.\nHazard escalation: Stopping work and obtaining qualified help for risks outside the technician's authorization or training.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-4.5", "title": "Control environmental risks", "core": 2, "objective": "4.5", "domain": 4, "type": "software", "requires": ["core2-4.4"], "lore": "Temperature, airflow, humidity, dust, liquids, and power quality affect equipment. Follow disposal and facility rules for batteries and electronics.\n\nYOUR TOOLKIT\n\nAirflow management — Maintaining intended intake and exhaust paths to remove heat.\n\nSurge protection — Reducing damage risk from specified transient electrical events.\n\nBattery recycling — Routing batteries through an approved handling and recycling process.\n\nHumidity control — Managing moisture conditions to reduce condensation and static-related risk.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A rack inlet is blocked by boxes. Restore airflow before increasing fan speed or replacing a healthy processor.", "questions": [{"id": "core2-4.5-practice-4-5-0", "prompt": "Which concept best fits this description? Maintaining intended intake and exhaust paths to remove heat.", "options": ["Airflow management", "Surge protection", "Humidity control", "Battery recycling"], "answer": 0, "explanation": "Airflow management: Maintaining intended intake and exhaust paths to remove heat. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-4.5-practice-4-5-1", "prompt": "Which concept best fits this description? Reducing damage risk from specified transient electrical events.", "options": ["Battery recycling", "Airflow management", "Humidity control", "Surge protection"], "answer": 3, "explanation": "Surge protection: Reducing damage risk from specified transient electrical events. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-4.5-match-4-5", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Airflow management", "Surge protection", "Battery recycling", "Humidity control"], "options": ["Routing batteries through an approved handling and recycling process.", "Maintaining intended intake and exhaust paths to remove heat.", "Managing moisture conditions to reduce condensation and static-related risk.", "Reducing damage risk from specified transient electrical events."], "answer": [1, 3, 0, 2], "explanation": "Airflow management: Maintaining intended intake and exhaust paths to remove heat.\nSurge protection: Reducing damage risk from specified transient electrical events.\nBattery recycling: Routing batteries through an approved handling and recycling process.\nHumidity control: Managing moisture conditions to reduce condensation and static-related risk.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-4.6", "title": "Respect privacy and licensing", "core": 2, "objective": "4.6", "domain": 4, "type": "software", "requires": ["core2-4.5"], "lore": "Handle only authorized data and use licensed software. Follow reporting and preservation requirements when encountering prohibited or sensitive material.\n\nYOUR TOOLKIT\n\nSoftware license — Terms governing authorized use and distribution of software.\n\nPersonally identifiable information — Information that identifies or can be linked to an individual under the applicable context.\n\nChain of custody — Recorded control and transfer of evidence.\n\nAcceptable use policy — Organizational rules for permitted use of technology and information.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A technician sees confidential files unrelated to the repair. Avoid unnecessary access and follow the organization's handling and reporting process.", "questions": [{"id": "core2-4.6-practice-4-6-0", "prompt": "Which concept best fits this description? Terms governing authorized use and distribution of software.", "options": ["Software license", "Personally identifiable information", "Acceptable use policy", "Chain of custody"], "answer": 0, "explanation": "Software license: Terms governing authorized use and distribution of software. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-4.6-practice-4-6-1", "prompt": "Which concept best fits this description? Information that identifies or can be linked to an individual under the applicable context.", "options": ["Chain of custody", "Software license", "Acceptable use policy", "Personally identifiable information"], "answer": 3, "explanation": "Personally identifiable information: Information that identifies or can be linked to an individual under the applicable context. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-4.6-match-4-6", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Software license", "Personally identifiable information", "Chain of custody", "Acceptable use policy"], "options": ["Recorded control and transfer of evidence.", "Terms governing authorized use and distribution of software.", "Organizational rules for permitted use of technology and information.", "Information that identifies or can be linked to an individual under the applicable context."], "answer": [1, 3, 0, 2], "explanation": "Software license: Terms governing authorized use and distribution of software.\nPersonally identifiable information: Information that identifies or can be linked to an individual under the applicable context.\nChain of custody: Recorded control and transfer of evidence.\nAcceptable use policy: Organizational rules for permitted use of technology and information.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-4.7", "title": "Communicate as part of the repair", "core": 2, "objective": "4.7", "domain": 4, "type": "software", "requires": ["core2-4.6"], "lore": "Listen, confirm the problem, set realistic expectations, explain impact, and obtain required authorization. Avoid blame, jargon, and unsupported promises.\n\nYOUR TOOLKIT\n\nActive listening — Confirming the user's meaning through attention and clarifying restatement.\n\nExpectation setting — Explaining likely next steps, timing, and uncertainty honestly.\n\nProfessional handoff — Transferring relevant context and responsibility clearly to the next support owner.\n\nResolution confirmation — Checking with the user that the original need has been addressed.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "Before a reset that removes data, explain the consequence and follow the approval process rather than surprising the user afterward.", "questions": [{"id": "core2-4.7-practice-4-7-0", "prompt": "Which concept best fits this description? Confirming the user's meaning through attention and clarifying restatement.", "options": ["Active listening", "Expectation setting", "Resolution confirmation", "Professional handoff"], "answer": 0, "explanation": "Active listening: Confirming the user's meaning through attention and clarifying restatement. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-4.7-practice-4-7-1", "prompt": "Which concept best fits this description? Explaining likely next steps, timing, and uncertainty honestly.", "options": ["Professional handoff", "Active listening", "Resolution confirmation", "Expectation setting"], "answer": 3, "explanation": "Expectation setting: Explaining likely next steps, timing, and uncertainty honestly. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-4.7-match-4-7", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Active listening", "Expectation setting", "Professional handoff", "Resolution confirmation"], "options": ["Transferring relevant context and responsibility clearly to the next support owner.", "Confirming the user's meaning through attention and clarifying restatement.", "Checking with the user that the original need has been addressed.", "Explaining likely next steps, timing, and uncertainty honestly."], "answer": [1, 3, 0, 2], "explanation": "Active listening: Confirming the user's meaning through attention and clarifying restatement.\nExpectation setting: Explaining likely next steps, timing, and uncertainty honestly.\nProfessional handoff: Transferring relevant context and responsibility clearly to the next support owner.\nResolution confirmation: Checking with the user that the original need has been addressed.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-4.8", "title": "Read scripts before running them", "core": 2, "objective": "4.8", "domain": 4, "type": "software", "requires": ["core2-4.7"], "lore": "Scripts can automate useful work and destructive mistakes. Understand inputs, permissions, dependencies, logging, and target paths before execution.\n\nYOUR TOOLKIT\n\nVariable — A named value used by script logic.\n\nConditional — A branch choosing behavior according to a tested condition.\n\nLoop — A structure repeating operations over a condition or collection.\n\nScript permission — The authority under which automated actions execute and therefore the extent of their possible impact.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A script recursively removes files. Inspect its target construction and test in a safe controlled setting before any approved production use.", "questions": [{"id": "core2-4.8-practice-4-8-0", "prompt": "Which concept best fits this description? A named value used by script logic.", "options": ["Variable", "Conditional", "Script permission", "Loop"], "answer": 0, "explanation": "Variable: A named value used by script logic. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-4.8-practice-4-8-1", "prompt": "Which concept best fits this description? A branch choosing behavior according to a tested condition.", "options": ["Loop", "Variable", "Script permission", "Conditional"], "answer": 3, "explanation": "Conditional: A branch choosing behavior according to a tested condition. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-4.8-match-4-8", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Variable", "Conditional", "Loop", "Script permission"], "options": ["A structure repeating operations over a condition or collection.", "A named value used by script logic.", "The authority under which automated actions execute and therefore the extent of their possible impact.", "A branch choosing behavior according to a tested condition."], "answer": [1, 3, 0, 2], "explanation": "Variable: A named value used by script logic.\nConditional: A branch choosing behavior according to a tested condition.\nLoop: A structure repeating operations over a condition or collection.\nScript permission: The authority under which automated actions execute and therefore the extent of their possible impact.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-4.9", "title": "Support remote access securely", "core": 2, "objective": "4.9", "domain": 4, "type": "software", "requires": ["core2-4.8"], "lore": "Use approved tools, verify the requester, obtain required consent, restrict access, and close the session when finished. Remote support is an access relationship, not just screen sharing.\n\nYOUR TOOLKIT\n\nRemote desktop — Interactive graphical access to another computer through an approved protocol or tool.\n\nRemote assistance — A support session that may involve user participation and controlled screen interaction.\n\nSession consent — Required user or organizational authorization for a remote support interaction.\n\nSession termination — Ending remote access and removing unnecessary persistent authorization after the task.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "An unsolicited caller requests remote control. Verify the request through known support channels rather than installing their suggested tool.", "questions": [{"id": "core2-4.9-practice-4-9-0", "prompt": "Which concept best fits this description? Interactive graphical access to another computer through an approved protocol or tool.", "options": ["Remote desktop", "Remote assistance", "Session termination", "Session consent"], "answer": 0, "explanation": "Remote desktop: Interactive graphical access to another computer through an approved protocol or tool. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-4.9-practice-4-9-1", "prompt": "Which concept best fits this description? A support session that may involve user participation and controlled screen interaction.", "options": ["Session consent", "Remote desktop", "Session termination", "Remote assistance"], "answer": 3, "explanation": "Remote assistance: A support session that may involve user participation and controlled screen interaction. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-4.9-match-4-9", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Remote desktop", "Remote assistance", "Session consent", "Session termination"], "options": ["Required user or organizational authorization for a remote support interaction.", "Interactive graphical access to another computer through an approved protocol or tool.", "Ending remote access and removing unnecessary persistent authorization after the task.", "A support session that may involve user participation and controlled screen interaction."], "answer": [1, 3, 0, 2], "explanation": "Remote desktop: Interactive graphical access to another computer through an approved protocol or tool.\nRemote assistance: A support session that may involve user participation and controlled screen interaction.\nSession consent: Required user or organizational authorization for a remote support interaction.\nSession termination: Ending remote access and removing unnecessary persistent authorization after the task.", "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}, {"id": "core2-4.10", "title": "Use AI with verification", "core": 2, "objective": "4.10", "domain": 4, "type": "software", "requires": ["core2-4.9"], "lore": "AI output can be useful but may be incorrect, fabricated, biased, or inappropriate for sensitive data. Apply organizational rules and verify consequential output.\n\nYOUR TOOLKIT\n\nGenerative AI — Systems producing new text or other content based on learned patterns and supplied context.\n\nHallucination — Plausible output that is incorrect or unsupported by reliable evidence.\n\nPrompt — Instructions and context supplied to guide a model's output.\n\nSensitive-data control — Restricting what private or regulated information may be shared with an AI service.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "An AI suggests a repair command. Read its effects, check authoritative guidance, and validate the target before using it.", "questions": [{"id": "core2-4.10-practice-4-10-0", "prompt": "Which concept best fits this description? Systems producing new text or other content based on learned patterns and supplied context.", "options": ["Generative AI", "Hallucination", "Sensitive-data control", "Prompt"], "answer": 0, "explanation": "Generative AI: Systems producing new text or other content based on learned patterns and supplied context. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-4.10-practice-4-10-1", "prompt": "Which concept best fits this description? Plausible output that is incorrect or unsupported by reliable evidence.", "options": ["Prompt", "Generative AI", "Sensitive-data control", "Hallucination"], "answer": 3, "explanation": "Hallucination: Plausible output that is incorrect or unsupported by reliable evidence. The other choices describe different mechanisms or properties.", "tier": 1}, {"id": "core2-4.10-match-4-10", "prompt": "Equip your toolkit: match each concept to its purpose.", "left": ["Generative AI", "Hallucination", "Prompt", "Sensitive-data control"], "options": ["Instructions and context supplied to guide a model's output.", "Systems producing new text or other content based on learned patterns and supplied context.", "Restricting what private or regulated information may be shared with an AI service.", "Plausible output that is incorrect or unsupported by reliable evidence."], "answer": [1, 3, 0, 2], "explanation": "Generative AI: Systems producing new text or other content based on learned patterns and supplied context.\nHallucination: Plausible output that is incorrect or unsupported by reliable evidence.\nPrompt: Instructions and context supplied to guide a model's output.\nSensitive-data control: Restricting what private or regulated information may be shared with an AI service.", "tier": 2}, {"id": "core2-4.10-scenario-4-10-0", "prompt": "An AI suggests a command you do not understand that removes a directory recursively.\n\nWhat should happen before any authorized use?", "options": ["Run it elevated immediately", "Inspect effects and targets, verify authoritative guidance, and test safely", "Assume confidence means correctness"], "answer": 1, "explanation": "Model output is not proof of safety or accuracy.", "tier": 3}, {"id": "core2-4.10-scenario-4-10-1", "prompt": "An AI suggests a command you do not understand that removes a directory recursively.\n\nWhat information should you avoid uploading to an unapproved AI service?", "options": ["A public manual title", "A generic error category", "Private credentials and sensitive customer data"], "answer": 2, "explanation": "Data-sharing must follow organizational privacy and security requirements.", "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA 220-1202 official objectives · document 4.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/cefedfb2b8a511ef809306d06d323538", "accessed": "2026-11-03"}, {"id": "technical", "title": "Microsoft Learn · Windows command reference", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands", "accessed": "2026-11-03"}]}];
